/* eslint-disable */
// ARQUIVO GERADO — não editar manualmente.
// Fonte: content/admin/gerador-criativos.html
// Regenerar com: node scripts/gen-gerador-criativos.mjs
export const GERADOR_CRIATIVOS_HTML: string = "<!DOCTYPE html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Gerador de Criativos — Attra Veículos</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Montserrat:ital,wght@0,200;0,300;0,400;0,500;0,600;0,700;0,800;0,900;1,600;1,700;1,800;1,900&family=Inter:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{\n    --bg:#101014; --panel:#1a1a20; --panel2:#22222a; --line:#2e2e38;\n    --txt:#f0f0f2; --muted:#9a9aa6; --red:#9a1c1c;\n  }\n  *{box-sizing:border-box; margin:0; padding:0;}\n  body{\n    background:var(--bg); color:var(--txt);\n    font-family:'Montserrat', -apple-system, sans-serif;\n    min-height:100vh;\n  }\n  header{\n    display:flex; align-items:center; gap:16px;\n    padding:14px 28px; border-bottom:1px solid var(--line);\n    background:var(--panel);\n  }\n  header .hdr-logo{height:32px; display:block;}\n  header small{color:var(--muted); font-weight:400; font-size:15px;}\n  .wrap{\n    display:flex; gap:28px; padding:28px; align-items:flex-start;\n    max-width:1400px; margin:0 auto; flex-wrap:wrap;\n  }\n  .form{\n    flex:1 1 480px; min-width:380px; max-width:640px;\n    display:flex; flex-direction:column; gap:18px;\n  }\n  fieldset{\n    border:1px solid var(--line); border-radius:12px;\n    background:var(--panel); padding:18px;\n  }\n  legend{\n    padding:0 8px; font-size:12px; font-weight:700; letter-spacing:2px;\n    text-transform:uppercase; color:var(--muted);\n  }\n  .row{display:flex; gap:12px;}\n  .row > *{flex:1;}\n  label{display:block; font-size:11px; font-weight:600; letter-spacing:1px;\n    text-transform:uppercase; color:var(--muted); margin:10px 0 5px;}\n  input[type=text]{\n    width:100%; background:var(--panel2); border:1px solid var(--line);\n    border-radius:8px; color:var(--txt); padding:10px 12px; font-size:14px;\n    font-family:inherit;\n  }\n  input[type=text]:focus{outline:none; border-color:var(--red);}\n  input[type=file]{\n    width:100%; font-size:12px; color:var(--muted); padding:8px 0;\n  }\n  input[type=file]::file-selector-button{\n    background:var(--panel2); border:1px solid var(--line); color:var(--txt);\n    border-radius:6px; padding:7px 12px; margin-right:10px; cursor:pointer;\n    font-family:inherit; font-size:12px; font-weight:600;\n  }\n  input[type=range]{width:100%; accent-color:var(--red);}\n  .sliders{display:grid; grid-template-columns:1fr 1fr 1fr; gap:10px; margin-top:6px;}\n  .sliders label{margin:4px 0 2px;}\n  .hint{font-size:11px; color:var(--muted); margin-top:6px; line-height:1.5;}\n  .estq-item{display:block; width:100%; text-align:left; background:var(--panel2);\n    border:1px solid var(--line); color:var(--txt); border-radius:8px;\n    padding:9px 12px; margin-top:8px; cursor:pointer; font-family:inherit; font-size:13px;}\n  .estq-item:hover{border-color:var(--red);}\n  #estoquefotos{display:flex; flex-wrap:wrap; gap:8px; margin-top:10px;}\n  .estq-thumb{width:86px; height:64px; object-fit:cover; border-radius:6px;\n    border:1px solid var(--line); cursor:pointer;}\n  .estq-thumb:hover{border-color:var(--red);}\n  .estq-thumb.usada{outline:2px solid var(--red); outline-offset:1px;}\n  .btn{\n    background:var(--red); color:#fff; border:none; border-radius:10px;\n    padding:16px 20px; font-size:15px; font-weight:700; letter-spacing:1px;\n    cursor:pointer; font-family:inherit; text-transform:uppercase;\n    transition:filter .15s;\n  }\n  .btn:hover{filter:brightness(1.12);}\n  .btn.secondary{background:var(--panel2); border:1px solid var(--line); font-weight:600; text-transform:none; letter-spacing:0;}\n  /* seletor de tipo */\n  .types{display:grid; grid-template-columns:1fr 1fr 1fr; gap:10px;}\n  .typebtn{\n    background:var(--panel2); border:2px solid var(--line); border-radius:10px;\n    color:var(--muted); padding:12px 8px; cursor:pointer; text-align:center;\n    font-family:inherit; font-size:13px; font-weight:700;\n  }\n  .typebtn small{display:block; font-weight:400; font-size:10px; margin-top:3px;}\n  .typebtn.active{border-color:var(--red); color:var(--txt);}\n  .carblock{\n    border:1px solid var(--line); border-radius:10px; padding:12px; margin-top:12px;\n    background:rgba(255,255,255,.02);\n  }\n  .carblock h4{font-size:12px; color:var(--red); letter-spacing:2px; margin-bottom:4px;}\n  .preview{\n    flex:0 0 auto; position:sticky; top:28px;\n    display:flex; flex-direction:column; gap:14px; align-items:center;\n  }\n  #cv{\n    width:378px; height:672px; border-radius:14px;\n    box-shadow:0 20px 60px rgba(0,0,0,.55); background:#000;\n  }\n  .preview .size{font-size:11px; color:var(--muted); letter-spacing:1px;}\n  @media (max-width:900px){ .preview{position:static;} }\n</style>\n</head>\n<body>\n\n<header>\n  <img class=\"hdr-logo\" src=\"/gerador/logo-branca.png\" alt=\"Attra Veículos\">\n  <div class=\"mark\"><small>Gerador de Criativos — Stories 1080×1920 + Feed 1080×1350</small></div>\n</header>\n\n<div class=\"wrap\">\n  <!-- ================= FORM ================= -->\n  <div class=\"form\">\n\n    <fieldset>\n      <legend>Tipo de criativo</legend>\n      <div class=\"types\">\n        <button class=\"typebtn active\" data-tipo=\"classico\">1 · Clássico<small>escuro, foto grande</small></button>\n        <button class=\"typebtn\" data-tipo=\"destaque\">2 · Destaque<small>claro, ficha técnica</small></button>\n        <button class=\"typebtn\" data-tipo=\"estoque\">3 · Estoque<small>lista de até 4 carros</small></button>\n        <button class=\"typebtn\" data-tipo=\"editorial\">4 · Editorial<small>luxo, minimalista</small></button>\n        <button class=\"typebtn\" data-tipo=\"ficha\">5 · Ficha<small>claro, 2 detalhes + destaque</small></button>\n        <button class=\"typebtn\" data-tipo=\"classico-loja\">6 · Clássico Loja<small>em teste — fundo da loja</small></button>\n      </div>\n    </fieldset>\n\n    <fieldset id=\"sec-edtema\" style=\"display:none\">\n      <legend id=\"rembg-legend\">Editorial — recorte da foto</legend>\n      <button class=\"btn secondary\" id=\"rembgbtn\" type=\"button\" style=\"width:100%; padding:12px; font-size:13px\">✂ REMOVER FUNDO DA FOTO (IA)</button>\n      <button class=\"btn secondary\" id=\"rembgundo\" type=\"button\" style=\"width:100%; padding:10px; font-size:12px; margin-top:8px; display:none\">↩ Voltar à foto original</button>\n      <div id=\"edrot-wrap\" style=\"margin-top:12px\"><label>Rotação do veículo (°)</label>\n        <input type=\"range\" id=\"edrot\" min=\"-180\" max=\"180\" value=\"0\"></div>\n      <div id=\"piso-recorte-wrap\" style=\"margin-top:12px; display:none\">\n        <label>Apagar o piso — quanto da base da foto</label>\n        <input type=\"range\" id=\"fatiapiso\" min=\"10\" max=\"55\" value=\"30\">\n        <div class=\"hint\">Só essa fatia de BAIXO da foto perde o fundo. O resto entra\n          inteiro — é o que protege vidros e reflexos de virarem buraco.</div>\n        <label style=\"margin-top:12px\">Força da sombra</label>\n        <input type=\"range\" id=\"sombra\" min=\"0\" max=\"130\" value=\"5\">\n      </div>\n      <div class=\"hint\" id=\"rembg-status\">Envie a Foto principal e clique acima — o carro é recortado\n        (~10-30s via IA) e composto no estúdio. Sem o recorte, a foto aparece inteira.</div>\n    </fieldset>\n\n    <fieldset id=\"sec-busca\">\n      <legend>Buscar do estoque (opcional)</legend>\n      <div class=\"row\">\n        <div style=\"flex:3\"><label>Veículo no estoque</label>\n          <input type=\"text\" id=\"estoquebusca\" placeholder=\"Ex.: Porsche 911, GLC 300, Purosangue...\"></div>\n        <div style=\"flex:1; display:flex; align-items:flex-end\">\n          <button class=\"btn secondary\" id=\"estoquebtn\" type=\"button\" style=\"width:100%; padding:11px 10px; font-size:12px\">BUSCAR</button></div>\n      </div>\n      <div id=\"estoqueresultados\"></div>\n      <div id=\"fichaslots\" style=\"display:none; margin-top:10px\">\n        <label style=\"margin-bottom:6px\">Clicar numa foto abaixo aplica em:</label>\n        <div class=\"types\" id=\"fichaslotbtns\">\n          <button class=\"slotbtn typebtn active\" data-slot=\"foto1\" type=\"button\">Principal<small>foto grande</small></button>\n          <button class=\"slotbtn typebtn\" data-slot=\"foto2\" type=\"button\">Detalhe 1<small>tira, esquerda</small></button>\n          <button class=\"slotbtn typebtn\" data-slot=\"foto3\" type=\"button\">Detalhe 2<small>tira, direita</small></button>\n        </div>\n        <div class=\"hint\">O destino avança sozinho a cada foto escolhida, então dá para clicar\n          nas quatro em sequência. Fora da Ficha, vale o atalho antigo: clique = principal,\n          Shift+clique = foto 2.</div>\n      </div>\n      <div id=\"estoquefotos\"></div>\n      <div class=\"hint\">Selecionar um veículo preenche os campos abaixo (tudo continua editável na mão).\n        Clique numa foto para usá-la como <strong>Foto principal</strong>; com Shift, vira a <strong>Foto 2</strong>.</div>\n    </fieldset>\n\n    <fieldset id=\"sec-veiculo\">\n      <legend>Veículo</legend>\n      <div class=\"row\">\n        <div><label>Marca</label><input type=\"text\" id=\"marca\" value=\"MERCEDES-BENZ\"></div>\n        <div><label>Ano</label><input type=\"text\" id=\"ano\" value=\"2024\"></div>\n      </div>\n      <label>Modelo</label>\n      <input type=\"text\" id=\"modelo\" value=\"C-300 AMG LINE\">\n      <div class=\"row\">\n        <div><label>Preço (só números)</label><input type=\"text\" id=\"preco\" value=\"335.000\"></div>\n        <div><label>Quilometragem</label><input type=\"text\" id=\"km\" value=\"34.760\"></div>\n      </div>\n      <div id=\"kmextra-wrap\">\n        <label>Complemento da linha do KM (opcional)</label>\n        <input type=\"text\" id=\"kmextra\" placeholder=\"Ex.: VEÍCULO COLECIONÁVEL\" value=\"\">\n      </div>\n    </fieldset>\n\n    <fieldset id=\"sec-destaques\">\n      <legend>Destaques (até 3, uma linha cada)</legend>\n      <input type=\"text\" id=\"b1\" value=\"Cor Cinza Selenita Magno\" style=\"margin-top:8px\">\n      <input type=\"text\" id=\"b2\" value=\"Motor 2.0 turbo gasolina 285 cv / 61,2 kgfm\" style=\"margin-top:8px\">\n      <input type=\"text\" id=\"b3\" value=\"Pacote AMG Line\" style=\"margin-top:8px\">\n      <div class=\"hint\">Deixe em branco para omitir. Cada destaque ocupa UMA linha —\n        a fonte encolhe até caber e, se ainda passar, corta com \"…\". Seja direto.</div>\n    </fieldset>\n\n    <fieldset id=\"sec-ficha\" style=\"display:none\">\n      <legend>Ficha do veículo</legend>\n      <div class=\"row\">\n        <div><label>Rótulo da 1ª linha</label><input type=\"text\" id=\"rot1\" placeholder=\"Ex.: EXTERIOR\" value=\"EXTERIOR\"></div>\n        <div><label>Conteúdo da 1ª linha</label><input type=\"text\" id=\"corext\" placeholder=\"Ex.: BLU ELETTRICO\" value=\"PRETO\"></div>\n      </div>\n      <div class=\"row\" style=\"margin-top:10px\">\n        <div><label>Rótulo da 2ª linha</label><input type=\"text\" id=\"rot2\" placeholder=\"Ex.: INTERIOR\" value=\"INTERIOR\"></div>\n        <div><label>Conteúdo da 2ª linha</label><input type=\"text\" id=\"corint\" placeholder=\"Ex.: CUOIO\" value=\"CARAMELO\"></div>\n      </div>\n      <div class=\"hint\">As duas linhas não precisam ser cor: sirvam para o que a peça pedir\n        (BLINDAGEM, MOTOR, PROCEDÊNCIA…). Rótulo vazio mostra só o conteúdo, sem os dois-pontos;\n        conteúdo vazio some com a linha inteira.</div>\n      <label style=\"margin-top:12px\">Selo do rodapé (garantia, programa)</label>\n      <input type=\"text\" id=\"garantia\" placeholder=\"Ex.: 2 ANOS DE GARANTIA\" value=\"2 ANOS DE GARANTIA\">\n      <div class=\"hint\">As três fotos de detalhe são as “Foto de baixo” da seção Fotos (interior, banco, roda).\n        A foto principal entra grande embaixo, com o fundo original — sem recorte.</div>\n    </fieldset>\n\n    <fieldset id=\"sec-specs\" style=\"display:none\">\n      <legend>Diferenciais do carro</legend>\n      <label>Separe por vírgula (viram pílulas vermelhas)</label>\n      <input type=\"text\" id=\"selo\" placeholder=\"Ex.: 7 LUGARES, BLINDADO, ZERO KM, FULL PPF\" value=\"BLINDADO\">\n      <div class=\"hint\">Até 4 diferenciais. O tamanho das pílulas se ajusta sozinho para caber na largura.</div>\n    </fieldset>\n\n    <fieldset id=\"sec-fotos\">\n      <legend>Fotos</legend>\n      <label id=\"foto1-label\">Foto principal (frente / 3-4)</label>\n      <input type=\"file\" id=\"foto1\" accept=\"image/*\">\n      <div class=\"sliders\">\n        <div><label>Zoom</label><input type=\"range\" id=\"f1zoom\" min=\"55\" max=\"250\" value=\"88\"></div>\n        <div><label>Posição ↔</label><input type=\"range\" id=\"f1x\" min=\"0\" max=\"100\" value=\"50\"></div>\n        <div><label>Posição ↕</label><input type=\"range\" id=\"f1y\" min=\"0\" max=\"100\" value=\"18\"></div>\n      </div>\n      <div class=\"hint\" id=\"foto1-hint\">A foto entra inteira — não precisa recortar o fundo. No Clássico, o bloco de preço acompanha a base da foto: mover a posição ↕ move o texto junto, e o carro nunca é cortado nem esmaecido.</div>\n      <label id=\"foto2-label\" style=\"margin-top:16px\">Foto secundária (traseira / lateral — rodapé)</label>\n      <input type=\"file\" id=\"foto2\" accept=\"image/*\">\n      <div class=\"sliders\">\n        <div><label>Zoom</label><input type=\"range\" id=\"f2zoom\" min=\"55\" max=\"250\" value=\"100\"></div>\n        <div><label>Posição ↔</label><input type=\"range\" id=\"f2x\" min=\"0\" max=\"100\" value=\"50\"></div>\n        <div><label>Posição ↕</label><input type=\"range\" id=\"f2y\" min=\"0\" max=\"100\" value=\"50\"></div>\n      </div>\n      <div id=\"piso-wrap\">\n        <label style=\"margin-top:12px\">Fundo da área de texto (Clássico)</label>\n        <div class=\"types\">\n          <button class=\"pisobtn typebtn active\" data-piso=\"perola\">Pérola<small>sólido claro</small></button>\n          <button class=\"pisobtn typebtn\" data-piso=\"concreto\">Concreto<small>piso claro real</small></button>\n          <button class=\"pisobtn typebtn\" data-piso=\"asfalto\">Asfalto<small>piso escuro real</small></button>\n        </div>\n        <label style=\"margin-top:12px\">Posição do piso (altura)</label>\n        <input type=\"range\" id=\"pisoy\" min=\"-60\" max=\"160\" value=\"-18\">\n        <div class=\"hint\">Desça o piso até a divisa ficar abaixo do veículo — a fusão nunca\n          deve cobrir o carro. O preço e os destaques acompanham.</div>\n      </div>\n      <div id=\"corte-wrap\">\n        <label style=\"margin-top:12px\">Altura do corte transversal (Clássico)</label>\n        <input type=\"range\" id=\"corte\" min=\"-160\" max=\"200\" value=\"-32\">\n        <div class=\"hint\">Arraste pra direita em carros ALTOS (mais área de foto);\n          pra esquerda em carros baixos (mais espaço pros destaques).</div>\n      </div>\n      <div id=\"fotos-extra\" style=\"display:none\">\n        <label style=\"margin-top:16px\">Foto de baixo 2 (Detalhe 2 na Ficha)</label>\n        <input type=\"file\" id=\"foto3\" accept=\"image/*\">\n        <div class=\"sliders\">\n          <div><label>Zoom</label><input type=\"range\" id=\"f3zoom\" min=\"100\" max=\"250\" value=\"100\"></div>\n          <div><label>Posição ↔</label><input type=\"range\" id=\"f3x\" min=\"0\" max=\"100\" value=\"50\"></div>\n          <div><label>Posição ↕</label><input type=\"range\" id=\"f3y\" min=\"0\" max=\"100\" value=\"50\"></div>\n        </div>\n        <div id=\"foto4-wrap\">\n          <label style=\"margin-top:12px\">Foto de baixo 3 (opcional)</label>\n          <input type=\"file\" id=\"foto4\" accept=\"image/*\">\n          <div class=\"sliders\">\n            <div><label>Zoom</label><input type=\"range\" id=\"f4zoom\" min=\"100\" max=\"250\" value=\"100\"></div>\n            <div><label>Posição ↔</label><input type=\"range\" id=\"f4x\" min=\"0\" max=\"100\" value=\"50\"></div>\n            <div><label>Posição ↕</label><input type=\"range\" id=\"f4y\" min=\"0\" max=\"100\" value=\"50\"></div>\n          </div>\n        </div>\n        <div class=\"hint\">No Destaque, com 1 foto o rodapé fica inteiro e com 3 vira uma tríade.\n          Na Ficha são duas na tira do topo — a posição e o zoom escolhem o trecho de cada uma.</div>\n      </div>\n    </fieldset>\n\n    <fieldset id=\"sec-estoque\" style=\"display:none\">\n      <legend>Lista de carros (até 4)</legend>\n      <div class=\"row\">\n        <div><label>Título — linha 1</label><input type=\"text\" id=\"et1\" value=\"NOVIDADES\"></div>\n        <div><label>Título — linha 2 (vermelho)</label><input type=\"text\" id=\"et2\" value=\"EM ESTOQUE!\"></div>\n      </div>\n      <div id=\"estoqueCars\"></div>\n      <div class=\"hint\">Carros sem nome e sem foto são omitidos; o espaçamento se ajusta sozinho. As fotos entram inteiras nos cards — sem recorte de fundo.</div>\n    </fieldset>\n\n    <fieldset>\n      <legend>Logo (opcional)</legend>\n      <input type=\"file\" id=\"logofile\" accept=\"image/png\">\n      <div class=\"hint\">As logos oficiais da Attra (branca e preta, do site) já vêm embutidas e são usadas conforme o fundo de cada formato. Envie um PNG transparente aqui apenas se quiser substituir a do formato Clássico.</div>\n      <button class=\"btn secondary\" id=\"clearlogo\" style=\"margin-top:10px; padding:9px 14px; font-size:12px;\">Voltar ao logo padrão</button>\n    </fieldset>\n\n    <button class=\"btn\" id=\"download\">⬇ Baixar Stories + Feed (envia ao Marketing)</button>\n    <div id=\"downloadmsg\" class=\"hint\" style=\"margin-top:10px\">Gera os dois PNGs — Stories 1080×1920 e Feed 1080×1350 (4:5, só a foto principal) — baixa no computador e envia os dois ao board do Marketing.</div>\n\n    <fieldset id=\"sec-status\" style=\"margin-top:18px\">\n      <legend>Publicar no Status do WhatsApp</legend>\n      <label>Legenda</label>\n      <textarea id=\"statuscaption\" rows=\"5\"\n        style=\"width:100%; padding:10px; border-radius:8px; border:1px solid var(--bd);\n               background:var(--bg2); color:var(--txt); font:inherit; resize:vertical\"\n        placeholder=\"Escreva a legenda do status...\"></textarea>\n      <label style=\"margin-top:12px\">Link (entra no fim da legenda)</label>\n      <input type=\"text\" id=\"statuslink\" placeholder=\"https://attraveiculos.com.br/veiculo/...\">\n      <div class=\"hint\">Selecionar um veículo na busca preenche o link com a ficha dele,\n        já marcada para o painel saber que a visita veio do status. Dá para editar.</div>\n      <button class=\"btn\" id=\"publicarstatus\" style=\"margin-top:12px\">Publicar no status (24h)</button>\n      <div id=\"statusmsg\" class=\"hint\" style=\"margin-top:10px\"></div>\n    </fieldset>\n  </div>\n\n  <!-- ================= PREVIEW ================= -->\n  <div class=\"preview\">\n    <canvas id=\"cv\" width=\"1080\" height=\"1920\"></canvas>\n    <div class=\"size\">PRÉVIA EM TEMPO REAL — EXPORTA STORIES 1080 × 1920 + FEED 1080 × 1350</div>\n  </div>\n</div>\n\n<script>\n'use strict';\n/* As imagens de fundo (fachadas, pisos, editorial e logos) saíram do base64\n   para /public/gerador/ em 29/08/2026: eram 1,04 MB que o iframe rebaixava a\n   cada abertura. Agora o navegador as cacheia. Ver\n   docs/superpowers/plans/2026-08-29-gerador-criativos-react.md */\nconst cv  = document.getElementById('cv');\n// `ctx` e `H` são `let` de propósito: renderFeed() troca os dois por um\n// canvas 1080×1350 e devolve — ver o bloco \"Feed 4:5\" depois de render().\nlet ctx = cv.getContext('2d');\nconst W = 1080, H_STORIES = 1920, H_FEED = 1350;\nlet H = H_STORIES;\nconst RED = '#9a1c1c';   // vermelho oficial Attra — R154 G28 B28\n\nconst state = {\n  tipo: 'classico',\n  foto1: null, foto2: null, foto3: null, foto4: null, logo: null,\n  // Enquadramento padrão da foto de cima, calibrado pela Lorrayne no próprio\n  // gerador (04/08/2026): recua o zoom para o carro não abrir espremido nas\n  // bordas e sobe o corte para o veículo ficar abaixo do título. Tem que casar\n  // com os value= dos sliders, senão a peça abre diferente do que eles mostram.\n  f1: {zoom:.88, x:.5, y:.18},\n  f2: {zoom:1, x:.5, y:.5},\n  f3: {zoom:1, x:.5, y:.5},\n  f4: {zoom:1, x:.5, y:.5},\n  estFotos: [null, null, null, null],\n  foto1Cut: null,   // foto principal com fundo removido (Editorial)\n  foto1Data: null,  // dataURL da foto original (upload manual → rembg)\n  foto1Url: null,   // URL pública da foto (estoque → rembg sem upload)\n  edRot: 0,         // rotação do carro recortado no Editorial (graus)\n  pisoTipo: 'perola', // fundo da área de texto do Clássico\n  slotFoto: 'foto1',  // destino do clique na galeria do estoque (Ficha)\n};\n\n/* ---------- logos oficiais embutidas ---------- */\nconst officialLogo = new Image();                 // branca (fundos escuros)\nofficialLogo.onload = () => render();\nofficialLogo.src = document.querySelector('.hdr-logo').src;\n\nlet blackLogo = null;                             // preta (fundos claros), branco→transparente\nconst blackLogoImg = new Image();\nblackLogoImg.onload = () => {\n  const c = document.createElement('canvas');\n  c.width = blackLogoImg.width; c.height = blackLogoImg.height;\n  const x = c.getContext('2d');\n  x.drawImage(blackLogoImg, 0, 0);\n  const d = x.getImageData(0, 0, c.width, c.height);\n  for(let i = 0; i < d.data.length; i += 4){\n    const r = d.data[i], g = d.data[i+1], b = d.data[i+2];\n    if((r+g+b)/3 > 232 && Math.abs(r-g) < 20 && Math.abs(g-b) < 20) d.data[i+3] = 0;\n  }\n  x.putImageData(d, 0, 0);\n  blackLogo = c;\n  render();\n};\nblackLogoImg.src = '/gerador/logo-preta.jpg';\n\n// cenário de estúdio do Editorial (palco elevado) — o carro recortado\n// é composto por cima\nconst edFundoImg = new Image();\nedFundoImg.onload = () => render();\nedFundoImg.src = '/gerador/fundo-editorial.jpg';\n\n// pisos — fundos da área de texto do Clássico (selecionáveis)\nconst pisoImgs = {};\nfor(const [k, src] of Object.entries({\n  concreto: '/gerador/piso-concreto.jpg',\n  asfalto: '/gerador/piso-asfalto.jpg',\n})){\n  const im = new Image();\n  im.onload = () => render();\n  im.src = src;\n  pisoImgs[k] = im;\n}\n\n// Fachada do Clássico ORIGINAL (1080x1264): recorte fechado do letreiro, que\n// o desenho original enquadra em escala 1.06 deslocada -60px e recorta na\n// janela 0..1000. NÃO é a mesma imagem da fachada ampla usada pelo Clássico\n// Loja — trocar uma pela outra desalinha o letreiro e o bloco de título.\nconst facadeClassicoImg = new Image();\nfacadeClassicoImg.onload = () => render();\nfacadeClassicoImg.src = '/gerador/fachada-classico.jpg';\n\n// fachada da loja (fundo do topo do formato Clássico — o letreiro é o logo)\nconst facadeImg = new Image();\nfacadeImg.onload = () => render();\nfacadeImg.src = '/gerador/fachada-loja.jpg';\n\n/* ---------- helpers ---------- */\nlet _grain = null;\nfunction grainCanvas(){\n  if(_grain) return _grain;\n  const c = document.createElement('canvas');\n  c.width = 256; c.height = 256;\n  const x = c.getContext('2d');\n  const d = x.createImageData(256, 256);\n  for(let i = 0; i < d.data.length; i += 4){\n    const v = 96 + (Math.random() * 64) | 0;\n    d.data[i] = d.data[i+1] = d.data[i+2] = v;\n    d.data[i+3] = 255;\n  }\n  x.putImageData(d, 0, 0);\n  _grain = c;\n  return c;\n}\n\nconst $ = id => document.getElementById(id);\nconst val = id => $(id).value.trim();\n\nfunction spacedText(text, cx, y, font, spacing, color){\n  ctx.font = font; ctx.fillStyle = color; ctx.textBaseline = 'alphabetic';\n  const chars = [...text];\n  let total = 0;\n  for(const ch of chars) total += ctx.measureText(ch).width + spacing;\n  total -= spacing;\n  let x = cx - total/2;\n  for(const ch of chars){\n    ctx.fillText(ch, x, y);\n    x += ctx.measureText(ch).width + spacing;\n  }\n  return total;\n}\nfunction spacedWidth(text, font, spacing){\n  ctx.font = font;\n  const chars = [...text];\n  let total = 0;\n  for(const ch of chars) total += ctx.measureText(ch).width + spacing;\n  return total - spacing;\n}\nfunction wrapLines(text, font, maxW){\n  ctx.font = font;\n  const words = text.split(/\\s+/), lines = [];\n  let cur = '';\n  for(const w of words){\n    const t = cur ? cur + ' ' + w : w;\n    if(ctx.measureText(t).width > maxW && cur){ lines.push(cur); cur = w; }\n    else cur = t;\n  }\n  if(cur) lines.push(cur);\n  return lines;\n}\nfunction rr(x, y, w, h, r){\n  ctx.beginPath();\n  ctx.moveTo(x+r, y);\n  ctx.arcTo(x+w, y,   x+w, y+h, r);\n  ctx.arcTo(x+w, y+h, x,   y+h, r);\n  ctx.arcTo(x,   y+h, x,   y,   r);\n  ctx.arcTo(x,   y,   x+w, y,   r);\n  ctx.closePath();\n}\nfunction drawPhoto(img, rx, ry, rw, rh, opt, mode){\n  opt = opt || {zoom:1, x:.5, y:.5};\n  ctx.save();\n  ctx.beginPath(); ctx.rect(rx, ry, rw, rh); ctx.clip();\n  // 'fit' = aspect fit (a foto inteira aparece, sem cortar o carro)\n  const base = mode === 'fit'\n    ? Math.min(rw/img.width, rh/img.height)\n    : Math.max(rw/img.width, rh/img.height);\n  const scale = base * opt.zoom;\n  const dw = img.width*scale, dh = img.height*scale;\n  const rangeX = Math.max(dw - rw, rw*.6);\n  const rangeY = Math.max(dh - rh, rh*.6);\n  const dx = rx + (rw-dw)/2 - (opt.x-.5)*rangeX;\n  const dy = ry + (rh-dh)/2 - (opt.y-.5)*rangeY;\n  if(dw < rw-1 || dh < rh-1){\n    if(mode === 'dark'){\n      // preenchimento escuro sólido (em vez de blur)\n      const gd = ctx.createLinearGradient(0, ry, 0, ry+rh);\n      gd.addColorStop(0, '#0a0a0c'); gd.addColorStop(1, '#1e1e22');\n      ctx.fillStyle = gd; ctx.fillRect(rx, ry, rw, rh);\n    } else {\n      const bs = base * 1.2;\n      ctx.filter = 'blur(45px)';\n      ctx.drawImage(img, rx+(rw-img.width*bs)/2, ry+(rh-img.height*bs)/2, img.width*bs, img.height*bs);\n      ctx.filter = 'none';\n      ctx.fillStyle = 'rgba(0,0,0,.38)';\n      ctx.fillRect(rx, ry, rw, rh);\n    }\n  }\n  ctx.drawImage(img, dx, dy, dw, dh);\n  if(mode === 'dark' && dy > ry + 2){\n    // funde o preenchimento escuro com o topo da foto (sem emenda visível)\n    const gb = ctx.createLinearGradient(0, dy - 2, 0, dy + 170);\n    gb.addColorStop(0, 'rgba(10,10,12,1)');\n    gb.addColorStop(1, 'rgba(10,10,12,0)');\n    ctx.fillStyle = gb;\n    ctx.fillRect(rx, Math.max(ry, dy - 2), rw, 172);\n  }\n  ctx.restore();\n}\nfunction autoFrameFoto1(img){\n  const rw = 1080, rh = 1000;\n  const base = Math.max(rw/img.width, rh/img.height);\n  // O `true ||` que existia aqui forçava o enquadramento neutro para TODOS os\n  // formatos. Fazia sentido enquanto só existia o Clássico Loja, cuja banda\n  // 540..1060 afunda o carro com o zoom calibrado. Com o Clássico ORIGINAL de\n  // volta, ele precisa da calibração .88/.18 feita na peça pronta — sem ela o\n  // carro sobe e encosta no título.\n  if(state.tipo !== 'classico' || img.width/img.height <= rw/rh + .05){\n    // Neutro para TODOS os casos desde a banda 540..1060 (14/08): o zoom .88 /\n    // y .18 abaixo era calibrado para a foto na faixa 0..1000 do desenho\n    // antigo, e na banda ele afundava e encolhia o carro.\n    state.f1 = {zoom:1, x:.5, y:.5};\n  } else {\n    // Enquadramento padrão do Clássico para foto horizontal, calibrado pela\n    // Lorrayne no próprio gerador (04/08/2026).\n    //\n    // O cálculo anterior era \"largura inteira, sem sobra nas laterais\": dava\n    // zoom .84 e y .37 na foto de referência. Ela ajustou para .88 e .18 — um\n    // pouco mais fechado e com a foto mais baixa, deixando o carro abaixo do\n    // título em vez de encostar nele.\n    //\n    // É valor fixo, não fórmula: a calibração foi feita a olho sobre a peça\n    // pronta, e não há regra derivável dela. Em foto de proporção muito\n    // diferente da usual (~1,29) pode ser preciso ajustar na mão — os controles\n    // estão logo ali e não brigam mais com o operador.\n    state.f1 = {zoom: .88, x: .5, y: .18};\n  }\n  $('f1zoom').value = state.f1.zoom*100;\n  $('f1x').value = state.f1.x*100;\n  $('f1y').value = state.f1.y*100;\n}\nfunction drawDefaultLogo(cx, cy, size){       // vetor reserva (se a imagem falhar)\n  const s = size/1000;\n  ctx.save();\n  ctx.translate(cx - 500*s, cy - 475*s);\n  ctx.scale(s, s);\n  ctx.fillStyle = '#ffffff';\n  ctx.beginPath();\n  ctx.moveTo(478,10); ctx.lineTo(568,10); ctx.lineTo(818,542); ctx.lineTo(668,542);\n  ctx.lineTo(524,180); ctx.lineTo(308,672); ctx.lineTo(206,631);\n  ctx.closePath(); ctx.fill();\n  ctx.beginPath();\n  ctx.moveTo(188,671); ctx.lineTo(290,713); ctx.lineTo(191,940); ctx.lineTo(71,940);\n  ctx.closePath(); ctx.fill();\n  ctx.fillStyle = RED;\n  ctx.beginPath();\n  ctx.moveTo(0,570); ctx.lineTo(820,570); ctx.lineTo(912,938);\n  ctx.closePath(); ctx.fill();\n  ctx.restore();\n}\nfunction placeholder(rx, ry, rw, rh, label, dark){\n  const g = ctx.createLinearGradient(rx, ry, rx, ry+rh);\n  if(dark === false){ g.addColorStop(0,'#d4d4d8'); g.addColorStop(1,'#bfbfc4'); }\n  else { g.addColorStop(0,'#15181c'); g.addColorStop(1,'#2a2f36'); }\n  ctx.fillStyle = g; ctx.fillRect(rx, ry, rw, rh);\n  ctx.fillStyle = dark === false ? 'rgba(0,0,0,.35)' : 'rgba(255,255,255,.25)';\n  ctx.font = '600 ' + Math.min(30, rh/5) + 'px Montserrat, sans-serif';\n  ctx.textAlign = 'center';\n  ctx.fillText(label, rx + rw/2, ry + rh*(rh > 500 ? .72 : .53));\n  ctx.textAlign = 'left';\n}\n// desenha a foto com bordas suaves (topo e laterais se fundem com o fundo)\n/**\n * `modo === 'fit'` mostra a FOTO INTEIRA; sem ele, preenche a caixa cortando.\n *\n * A foto do estoque é horizontal (~1,29) e a caixa do Clássico é quase quadrada\n * (1080x1000 = 1,08). Preenchendo, a foto era ampliada até encher a ALTURA e\n * perdia 205px de largura — 102 por lado —, o que come a frente e a traseira do\n * carro e faz a peça abrir já com o veículo espremido nas bordas. Em fit o\n * zoom 100% passa a significar \"a foto inteira\", que é o que o operador espera,\n * e ele amplia a partir dali se quiser.\n *\n * NÃO está ligado no Clássico. Ligar sozinho piora: a foto passa a ocupar\n * 1080x840 numa caixa de 1000 de altura, sobra faixa vazia embaixo, e o logo e\n * o título — posicionados a partir de `topGap` — colidem com o letreiro que\n * aparece na própria foto. O enquadramento do Clássico depende da caixa e da\n * foto terem a mesma proporção; mudar isso é mexer no layout inteiro da peça,\n * não num parâmetro.\n */\nfunction drawPhotoFeather(img, rx, ry, rw, rh, opt, modo){\n  opt = opt || {zoom:1, x:.5, y:.5};\n  const base  = modo === 'fit'\n    ? Math.min(rw/img.width, rh/img.height)\n    : Math.max(rw/img.width, rh/img.height);\n  const scale = base * opt.zoom;\n  const dw = img.width*scale, dh = img.height*scale;\n  const rangeX = Math.max(dw - rw, rw*.6);\n  const rangeY = Math.max(dh - rh, rh*.6);\n  const dx = rx + (rw-dw)/2 - (opt.x-.5)*rangeX;\n  const dy = ry + (rh-dh)/2 - (opt.y-.5)*rangeY;\n  const oc = document.createElement('canvas');\n  oc.width = Math.ceil(dw); oc.height = Math.ceil(dh);\n  const o = oc.getContext('2d');\n  o.drawImage(img, 0, 0, dw, dh);\n  o.globalCompositeOperation = 'destination-out';\n  let g;\n  if(dy > ry + 2){                    // borda superior esfumada\n    g = o.createLinearGradient(0, 0, 0, 180);\n    g.addColorStop(0, 'rgba(0,0,0,1)'); g.addColorStop(1, 'rgba(0,0,0,0)');\n    o.fillStyle = g; o.fillRect(0, 0, oc.width, 180);\n  }\n  if(dw < rw - 4){                    // bordas laterais esfumadas\n    g = o.createLinearGradient(0, 0, 110, 0);\n    g.addColorStop(0, 'rgba(0,0,0,1)'); g.addColorStop(1, 'rgba(0,0,0,0)');\n    o.fillStyle = g; o.fillRect(0, 0, 110, oc.height);\n    g = o.createLinearGradient(oc.width, 0, oc.width - 110, 0);\n    g.addColorStop(0, 'rgba(0,0,0,1)'); g.addColorStop(1, 'rgba(0,0,0,0)');\n    o.fillStyle = g; o.fillRect(oc.width - 110, 0, 110, oc.height);\n  }\n  ctx.save();\n  ctx.beginPath(); ctx.rect(rx, ry, rw, rh); ctx.clip();\n  ctx.drawImage(oc, dx, dy);\n  ctx.restore();\n  return dy;\n}\nfunction drawLogoWhite(cx, cy, maxW){\n  if(state.logo){\n    const lw = state.logo.width/state.logo.height > 2 ? maxW : maxW*.45;\n    const lh = state.logo.height/state.logo.width * lw;\n    ctx.drawImage(state.logo, cx - lw/2, cy - lh/2, lw, lh);\n  } else if(officialLogo.complete && officialLogo.naturalWidth){\n    const lh = officialLogo.height/officialLogo.width * maxW;\n    ctx.drawImage(officialLogo, cx - maxW/2, cy - lh/2, maxW, lh);\n  } else drawDefaultLogo(cx, cy, 148);\n}\nfunction drawLogoBlack(cx, cy, maxW){\n  if(blackLogo){\n    const lh = blackLogo.height/blackLogo.width * maxW;\n    ctx.drawImage(blackLogo, cx - maxW/2, cy - lh/2, maxW, lh);\n  }\n}\n\n/**\n * Só calcula onde o recorte fica na peça — não desenha.\n *\n * O carro é desenhado mais adiante, DEPOIS do bloco de texto, para ficar em\n * primeiro plano sobre o fundo sem que nada o cubra.\n */\n/** Caixa real do veículo dentro do recorte (limites do alpha), em frações. */\nfunction bboxDoRecorte(recorte){\n  if(recorte._bbox) return recorte._bbox;\n  const P = 220;\n  const oc = document.createElement('canvas'); oc.width = P; oc.height = P;\n  const o = oc.getContext('2d');\n  o.drawImage(recorte, 0, 0, P, P);\n  const px = o.getImageData(0, 0, P, P).data;\n  let x0 = P, x1 = 0, y0 = P, y1 = 0;\n  for(let y = 0; y < P; y++) for(let x = 0; x < P; x++){\n    if(px[(y*P + x)*4 + 3] > 24){\n      if(x < x0) x0 = x; if(x > x1) x1 = x;\n      if(y < y0) y0 = y; if(y > y1) y1 = y;\n    }\n  }\n  return (recorte._bbox = { x0: x0/P, x1: (x1+1)/P, y0: y0/P, y1: (y1+1)/P });\n}\n\n/**\n * Foto com SÓ O PISO apagado, na janela do Clássico — a versão que a Lorrayne\n * aprovou, restaurada. (Numa rodada intermediária ela foi substituída pelo\n * recorte puro e o slider \"Apagar o piso\" ficou na tela sem efeito nenhum.)\n *\n * A máscara do recorte vale apenas nos últimos `fatia` da foto: o chão dela\n * some e o pátio do fundo aparece no lugar. Acima disso a foto entra INTACTA —\n * vidros, reflexos, loja — que é o que protege as janelas de virarem buraco\n * (G 63, 14/08). E a base é ancorada no pé da janela, como no modo foto\n * inteira: as rodas nunca são cortadas, em nenhum ajuste.\n */\nfunction fotoComPisoApagado(foto, recorte, rx, ry, rw, rh, opt, fatia){\n  opt = opt || {zoom:1, x:.5, y:.5};\n  // Posição vertical LIVRE (opt.y). Numa rodada eu apliquei aqui a âncora de\n  // base do modo foto-inteira e o slider ↕ ficou sem efeito nenhum — erro meu.\n  // Aqui a âncora é desnecessária: o texto se prende à base REAL do carro\n  // (medida no alpha), então mover a foto move o bloco de texto junto e nada\n  // é cortado.\n  const scale = Math.max(rw/foto.width, rh/foto.height) * opt.zoom;\n  const dw = foto.width*scale, dh = foto.height*scale;\n  const dx = rx + (rw-dw)/2 - (opt.x-.5)*Math.max(dw - rw, rw*.6);\n  const dy = ry + (rh-dh)/2 - (opt.y-.5)*Math.max(dh - rh, rh*.6);\n\n  const L = Math.max(1, Math.ceil(dw)), A = Math.max(1, Math.ceil(dh));\n  const yCorte = Math.round(A * (1 - fatia));    // onde o apagamento começa\n\n  const m = document.createElement('canvas'); m.width = L; m.height = A;\n  const mc = m.getContext('2d');\n  mc.drawImage(recorte, 0, 0, L, A);             // alpha do carro embaixo…\n  mc.fillStyle = '#fff';\n  mc.fillRect(0, 0, L, yCorte);                  // …foto intacta acima\n  // 24px de degradê: a divisa não vira régua, e sobra uma tira do piso\n  // ORIGINAL colada no carro — onde vive a sombra de contato real.\n  const g = mc.createLinearGradient(0, yCorte, 0, yCorte + 24);\n  g.addColorStop(0, 'rgba(255,255,255,1)');\n  g.addColorStop(1, 'rgba(255,255,255,0)');\n  mc.fillStyle = g; mc.fillRect(0, yCorte, L, 24);\n\n  const f = document.createElement('canvas'); f.width = L; f.height = A;\n  const fc = f.getContext('2d');\n  fc.imageSmoothingQuality = 'high';\n  fc.drawImage(foto, 0, 0, L, A);\n  fc.globalCompositeOperation = 'destination-in';\n  fc.drawImage(m, 0, 0);\n  // SEM fusão no topo. Eu havia posto 70px aqui e não era nada do combinado:\n  // a foto tem que entrar inteira acima da fatia do piso.\n\n  // Sombra ANTES da foto: onde a máscara apagou o chão ela aparece; onde a\n  // foto é opaca (carro, tira de piso original) ela fica escondida atrás —\n  // nunca por cima do veículo. Duas camadas: ambiente larga + contato curta.\n  const baseD = baseDoRecorte(recorte, dy, dh);\n  // `|| 55` aqui era armadilha: parseInt('0') é 0, que é falsy, então arrastar\n  // a sombra até o fim ESQUERDO devolvia 55 — o oposto do que o operador fez.\n  // Passou despercebido enquanto o default era 55 e ninguém encostava no zero;\n  // com o default em 5 o zero fica a um passo. Number.isFinite separa \"zero\"\n  // de \"não é número\".\n  const bruto = parseInt($('sombra').value, 10);\n  const forca = (Number.isFinite(bruto) ? bruto : 5) / 100;\n  const sil = document.createElement('canvas'); sil.width = L; sil.height = A;\n  const sc = sil.getContext('2d');\n  sc.drawImage(recorte, 0, 0, L, A);\n  sc.globalCompositeOperation = 'source-in';\n  sc.fillStyle = '#000'; sc.fillRect(0, 0, L, A);\n  ctx.save();\n  // Clip só do topo até o fim da peça: embaixo nada corta o veículo — o que\n  // sobra ali já foi apagado pela máscara, e o texto se ancora abaixo dele.\n  ctx.beginPath(); ctx.rect(rx, ry, rw, H - ry); ctx.clip();\n  ctx.filter = 'blur(32px)';\n  ctx.globalAlpha = .28 * forca;\n  ctx.drawImage(sil, dx + dw*.03, baseD - dh*.13, dw*.94, dh*.20);\n  ctx.filter = 'blur(8px)';\n  ctx.globalAlpha = .80 * forca;\n  ctx.drawImage(sil, dx + dw*.10, baseD - dh*.045, dw*.80, dh*.065);\n  ctx.filter = 'none'; ctx.globalAlpha = 1;\n  ctx.drawImage(f, dx, dy);\n  ctx.restore();\n\n  return { dx, dy, dw, dh, baseDoCarro: baseD };\n}\n\n/**\n * Linha em que o carro encosta no chão, em coordenadas da peça.\n *\n * Vem da última linha OPACA do recorte — a base do pneu, não a borda da foto.\n * É o que permite a divisa do piso se posicionar sozinha: em carro alto (G 63,\n * picape) a divisa fixa cortava as rodas, e o operador tinha que corrigir na\n * mão toda vez.\n */\nfunction baseDoRecorte(recorte, dy, dh){\n  const P = 220;                                  // amostra reduzida: basta a linha\n  const oc = document.createElement('canvas'); oc.width = P; oc.height = P;\n  const o = oc.getContext('2d');\n  o.drawImage(recorte, 0, 0, P, P);\n  const px = o.getImageData(0, 0, P, P).data;\n  for(let y = P - 1; y >= 0; y--){\n    for(let x = 0; x < P; x += 2){\n      if(px[(y*P + x)*4 + 3] > 24) return dy + (y / P) * dh;\n    }\n  }\n  return dy + dh;\n}\n\n/**\n * Foto inteira na banda do carro (540..1060), com fusão no topo E na base.\n *\n * Antes a foto ocupava 0..1000 — cobria o letreiro do fundo novo, brigava com\n * o título e deixava o preço fixo em 1000: ajustar a posição vertical virava\n * uma luta entre três sliders (relato da Lorrayne, 14/08). Agora foto inteira\n * e recorte vivem na MESMA janela, abaixo do título e acima do preço: o\n * slider ↕ move a foto DENTRO da janela e nunca desloca o resto da peça.\n */\nfunction drawPhotoBanda(img, rx, ry, rw, rh, opt){\n  opt = opt || {zoom:1, x:.5, y:.5};\n  // Posição vertical LIVRE, e mesmo assim sem cortar o carro.\n  //\n  // A garantia não vem mais de travar o slider (eu havia removido o controle\n  // e isso deixou você sem poder enquadrar). Vem de a DIVISA acompanhar a\n  // foto: quem manda no início do bloco de texto é a borda de baixo da foto,\n  // devolvida por esta função. Mover a foto move o texto junto, e como as\n  // rodas nunca encostam na borda inferior da própria foto, elas nunca são\n  // atingidas — nem por corte, nem por transparência.\n  const scale = Math.max(rw/img.width, rh/img.height) * opt.zoom;\n  const dw = img.width*scale, dh = img.height*scale;\n  const dx = rx + (rw-dw)/2 - (opt.x-.5)*Math.max(dw - rw, rw*.6);\n  const dy = ry + (rh-dh)/2 - (opt.y-.5)*Math.max(dh - rh, rh*.6);\n\n  const altura = Math.max(rh, Math.ceil(dy + dh - ry));\n  const oc = document.createElement('canvas');\n  oc.width = rw; oc.height = altura;\n  const o = oc.getContext('2d');\n  o.imageSmoothingQuality = 'high';\n  o.drawImage(img, dx - rx, dy - ry, dw, dh);\n  o.globalCompositeOperation = 'destination-out';\n  // Fusão SÓ no topo, onde vive céu/fachada da foto — nunca o carro.\n  //\n  // A base é CORTE SECO, de propósito. Havia 90px de fusão aqui e ela comia\n  // o pneu (14/08) — os pneus vivem exatamente no pé da banda. É a mesma\n  // lição que este arquivo já registrava sobre o véu do desenho antigo:\n  // \"lavava a borracha e a sombra de contato — a divisa seca é preferível a\n  // estragar o veículo, que é o assunto da peça\". O carro tem prioridade\n  // máxima; efeito de acabamento nunca pode tocá-lo.\n  const topoFoto = Math.max(0, dy - ry);\n  let g = o.createLinearGradient(0, topoFoto, 0, topoFoto + 70);\n  g.addColorStop(0, 'rgba(0,0,0,1)'); g.addColorStop(1, 'rgba(0,0,0,0)');\n  o.fillStyle = g; o.fillRect(0, topoFoto, rw, 70);\n\n  ctx.save();\n  ctx.beginPath(); ctx.rect(rx, ry, rw, H - ry); ctx.clip();\n  ctx.drawImage(oc, rx, ry);\n  ctx.restore();\n  // topo: clampado na janela (o chamador usa para decidir o logo de reserva —\n  // com dy negativo ele desenhava um ATTRA duplicado sobre o letreiro).\n  // base: onde a foto termina — é o que ancora o bloco de texto.\n  return { topo: Math.max(ry, dy), base: dy + dh };\n}\n\n/* ================================================================\n   TIPO 1 — CLÁSSICO (escuro, foto grande)\n================================================================ */\nfunction renderClassicoLoja(){\n  const FEED = H === H_FEED;   // 1080×1350: só a foto principal, rodapé fecha mais cedo\n  const PHOTO1_H = 1000;\n\n  // Fundo ÚNICO: uma foto só da loja, sangrando na peça inteira — letreiro em\n  // cima, vitrine no meio, pátio embaixo. Substitui a montagem antiga (close do\n  // letreiro no topo + faixa de piso desenhado embaixo).\n  //\n  // Com o carro recortado pousando neste chão e o piso da foto dele apagado,\n  // existe UM piso só na peça. A diferença de tom que motivou tudo isso deixa\n  // de existir por construção, em vez de ser corrigida.\n  if(facadeImg.complete && facadeImg.naturalWidth){\n    // Puxada para CIMA: medido na imagem, as letras do \"ATTRA\" começam na\n    // linha 157 — o deslocamento de -117 as coloca em y=40, no topo da peça.\n    // Com o letreiro lá em cima, o bloco de título vive ABAIXO dele e a marca\n    // do veículo nunca mais disputa espaço com o nome da loja.\n    const DESLOC_Y = -117;\n    // Sempre na escala do Stories (H_STORIES), mesmo no Feed: o DESLOC_Y foi\n    // medido nessa escala e é o que põe o letreiro em y=40. O Feed só recorta\n    // a parte de baixo do fundo.\n    const esc = Math.max(W / facadeImg.naturalWidth, H_STORIES / facadeImg.naturalHeight);\n    ctx.drawImage(facadeImg,\n      (W - facadeImg.naturalWidth*esc)/2, DESLOC_Y,\n      facadeImg.naturalWidth*esc, facadeImg.naturalHeight*esc);\n  } else {\n    ctx.fillStyle = '#101013'; ctx.fillRect(0, 0, W, H);\n  }\n\n  // foto do carro com bordas esfumadas, fundida na fachada\n  // Com recorte, a foto é desenhada DEPOIS da faixa de piso — o piso precisa\n  // aparecer por trás do carro, no lugar do chão que a máscara apagou. Sem\n  // recorte, tudo segue como antes.\n  const comRecorte = !!(state.foto1 && state.foto1Cut);\n  let baseDoCarro = null, posCarro = null, baseDaFoto = null;\n\n  // Até onde o carro pode descer sem espremer o texto.\n  //\n  // A divisa acompanha a base do veículo, então descer a foto empurrava o\n  // bloco para baixo até os destaques serem cortados pela borda da faixa\n  // (14/08). O bloco tem tamanho conhecido — preço (+54), KM (+102),\n  // destaques a partir de +156, três linhas de 44 com respiro mínimo de 20 —\n  // e a faixa termina no corte da foto 2. Daí sai o limite: além dele o\n  // slider simplesmente para, em vez de estragar a peça.\n  const CUT_ = FEED ? H : 1416 - (parseInt($('corte').value, 10) || 0);\n  const ALTURA_TEXTO = FEED\n    ? 156 + 3*42 + 2*16 + 20                      // Feed: linhas de 42, respiro 16, sem diagonal\n    : 156 + 3*44 + 2*20 + 46;                     // = 374 até a borda da faixa\n  const BASE_MAX = CUT_ - ALTURA_TEXTO;\n\n  // A FAIXA DA FOTO TERMINA ONDE O TEXTO COMEÇA.\n  //\n  // A faixa era fixa em 520 (540..1060) enquanto o início do bloco de texto\n  // sobe junto com o corte. Passando de corte -18, BASE_MAX cai abaixo de 1060\n  // e o preço passava a ser desenhado EM CIMA da foto — foi assim que a peça da\n  // RAM saiu, com \"R$ 335.000\" fantasma sobre a roda. O slider do corte, que é\n  // justamente o que se usa para caber uma picape no rodapé, estragava o texto.\n  //\n  // Derivando a altura da faixa do mesmo limite que segura o texto, subir o\n  // corte passa a trocar foto principal por rodapé — nunca sobrepor um ao\n  // outro. O piso do slider (300) existe para a faixa não colapsar: além disso\n  // não há peça, há uma tira.\n  // Feed: a faixa sobe para logo abaixo do ano. Uma foto 4:3 full-bleed tem\n  // 810px de altura; com a faixa em 540 o carro só terminava perto de 1100 e\n  // o preço caía nas rodas (medido no G 63, 24/08). Subindo 100px, a base do\n  // carro fica acima de BASE_MAX e o bloco de texto cabe embaixo. O topo da\n  // foto é esfumado em 70px, então ela funde no escuro sob o título.\n  const BANDA_TOPO = FEED ? 440 : 540;\n  const pisoShiftPre = parseInt($('pisoy').value, 10) || 0;\n  const BANDA_H = Math.max(300, Math.min(520, BASE_MAX + Math.min(0, pisoShiftPre) - BANDA_TOPO));\n\n  let topGap = PHOTO1_H;\n  if(comRecorte){\n    // Apaga SÓ O PISO da foto (fatia do slider); o resto entra intacto.\n    // A janela é a mesma do modo foto inteira (abaixo do título), então o\n    // letreiro do fundo nunca é coberto — e o preço se ancora na base real do\n    // carro, medida no alpha do recorte.\n    const fatia = (parseInt($('fatiapiso').value, 10) || 30) / 100;\n    const r = fotoComPisoApagado(state.foto1, state.foto1Cut, 0, BANDA_TOPO, W, BANDA_H, state.f1, fatia);\n    topGap = Math.max(540, r.dy);\n    baseDoCarro = r.baseDoCarro;\n    posCarro = r;\n  } else if(state.foto1){\n    const r = drawPhotoBanda(state.foto1, 0, BANDA_TOPO, W, BANDA_H, state.f1);\n    topGap = Math.max(0, r.topo);\n    baseDaFoto = r.base;\n  } else {\n    ctx.fillStyle = 'rgba(255,255,255,.45)';\n    ctx.font = '600 26px Montserrat, sans-serif';\n    ctx.textAlign = 'center';\n    ctx.fillText('ENVIE A FOTO PRINCIPAL DO VEÍCULO', W/2, 750);\n    ctx.textAlign = 'left';\n  }\n\n  // gradiente p/ legibilidade do título\n  let g;\n  if(topGap < 150){\n    // foto cobre o letreiro (ex.: foto vertical ou zoom alto) — comportamento antigo\n    g = ctx.createLinearGradient(0, 0, 0, 760);\n    g.addColorStop(0, 'rgba(0,0,0,.62)');\n    g.addColorStop(.55, 'rgba(0,0,0,.28)');\n    g.addColorStop(1, 'rgba(0,0,0,0)');\n    ctx.fillStyle = g; ctx.fillRect(0, 0, W, 760);\n  } else {\n    // preserva o brilho do letreiro; escurece só a área do título\n    g = ctx.createLinearGradient(0, 170, 0, 780);\n    g.addColorStop(0, 'rgba(0,0,0,0)');\n    g.addColorStop(.22, 'rgba(0,0,0,.60)');\n    g.addColorStop(.48, 'rgba(0,0,0,.48)');\n    g.addColorStop(.75, 'rgba(0,0,0,.22)');\n    g.addColorStop(1, 'rgba(0,0,0,0)');\n    ctx.fillStyle = g; ctx.fillRect(0, 170, W, 610);\n  }\n\n\n\n  // logo desenhado só quando a foto cobre o letreiro da fachada\n  if(topGap < 150) drawLogoWhite(W/2, 168, 340);\n\n  const marca  = val('marca').toUpperCase();\n  const modelo = val('modelo').toUpperCase();\n  const ano    = val('ano');\n\n  // sombra suave para o título não se perder no fundo da fachada/foto\n  ctx.save();\n  ctx.shadowColor = 'rgba(0,0,0,.85)';\n  ctx.shadowBlur = 30;\n  ctx.shadowOffsetY = 3;\n\n  // Título colado no letreiro. Medido no fundo já deslocado: o letreiro ocupa\n  // 40-203 (base do \"VEÍCULOS\") e a faixa preta da fachada só termina em 471,\n  // onde começa a vegetação. O bloco vive nesses 268px — marca em 270, modelo\n  // em 368, ano em 424 — então cabe inteiro no preto, sem encostar nas\n  // trepadeiras, e lê como continuação do letreiro em vez de um bloco solto.\n  //\n  // O respiro entre as linhas é o que sobra da altura de cada fonte: o modelo\n  // pode chegar a 92px, então sua caixa alta começa ~66px acima da base. Com\n  // marca em 270 e modelo em 342 sobravam 6px entre uma linha e outra e o\n  // bloco lia como um carimbo só. 368 abre 32px ali, e o ano em 424 repete o\n  // mesmo respiro embaixo — ainda com 41px de folga até a vegetação.\n  if(marca) spacedText(marca, W/2, 270, '600 30px Montserrat, sans-serif', 11, '#ffffff');\n\n  // Largura máxima 920 (era 980): em nome longo — \"2500 LARAMIE\" — a linha\n  // chegava a 60px de cada borda e lia como se fosse estourar a peça. 920 dá\n  // 80px de margem, que é a mesma respiração do bloco de destaques.\n  let msize = 92, mspace = 26;\n  while(msize > 40 && spacedWidth(modelo, `200 ${msize}px Montserrat, sans-serif`, mspace) > 920){\n    msize -= 3; mspace = Math.max(8, mspace - 1);\n  }\n  if(modelo) spacedText(modelo, W/2, 368, `200 ${msize}px Montserrat, sans-serif`, mspace, '#ffffff');\n\n  if(ano){\n    const yy = 424;\n    const tw = spacedText(ano, W/2, yy, '300 34px Montserrat, sans-serif', 15, '#ffffff');\n    ctx.strokeStyle = 'rgba(255,255,255,.85)'; ctx.lineWidth = 1.5;\n    ctx.beginPath();\n    ctx.moveTo(W/2 - tw/2 - 195, yy - 11); ctx.lineTo(W/2 - tw/2 - 40, yy - 11);\n    ctx.moveTo(W/2 + tw/2 + 40,  yy - 11); ctx.lineTo(W/2 + tw/2 + 195, yy - 11);\n    ctx.stroke();\n  }\n\n  ctx.restore(); // fim da sombra do título\n\n  // corte transversal ajustável (slider): positivo sobe, negativo desce\n  const corte = parseInt($('corte').value, 10) || 0;\n  // Feed 4:5: não há foto de baixo — o piso vai até a borda, sem diagonal.\n  const CUT = FEED ? H : 1416 - corte;\n  // diagonal de volta (assinatura do layout): 40px de inclinação\n  const DIAG_L = FEED ? H : CUT + 20, DIAG_R = FEED ? H : CUT - 20;\n  const areaPath = () => {\n    ctx.beginPath();\n    ctx.moveTo(0, PISO_TOP); ctx.lineTo(W, PISO_TOP);\n    ctx.lineTo(W, DIAG_R); ctx.lineTo(0, DIAG_L);\n    ctx.closePath();\n  };\n\n  // Sem faixa de piso desenhada: o chão da peça é o da própria foto de fundo.\n  // O `pisoy` sobra como ajuste fino da altura do bloco de texto, e o `corte`\n  // continua definindo onde entra a foto de baixo.\n  const pisoShift = pisoShiftPre;\n  // Com recorte: ancora na base real do carro. Sem recorte: no pé da banda da\n  // foto — o texto nunca depende de onde o slider ↕ deixou a foto.\n  // A divisa acompanha a base do veículo, MAS nunca passa de BASE_MAX: além\n  // dele o bloco de texto não caberia inteiro e os destaques eram cortados.\n  // A trava é no TEXTO, não na foto — travar a foto prendia o slider em quase\n  // toda a faixa, que não é o que se quer: o enquadramento continua livre.\n  const pisoBruto = baseDoCarro !== null\n    ? Math.round(baseDoCarro) + 30                    // recorte: base real do carro\n    : (baseDaFoto !== null ? Math.round(baseDaFoto) : BANDA_TOPO + BANDA_H + 4);  // foto inteira: base da faixa\n  const PISO_TOP = Math.min(pisoBruto, BASE_MAX) + pisoShift;\n\n\n  // SEM véu sobre a foto.\n  //\n  // Havia aqui um degradê branco (até 42% de opacidade) pintado sobre os\n  // ÚLTIMOS 110px DA FOTO, para a passagem foto→piso não ler como linha dura.\n  // O custo era alto demais: essa faixa é justamente onde ficam os pneus e o\n  // chão sob o carro, e o véu lavava a borracha e a sombra de contato — o carro\n  // parecia flutuar. A divisa seca é preferível a estragar o veículo, que é o\n  // assunto da peça. (A fusão do topo do piso já era 0 pelo mesmo motivo.)\n\n  // paleta dos textos conforme o fundo\n  // Piso desta foto é concreto CLARO — medido: luminância 148-188 abaixo da\n  // linha 800, contra 9-34 na vitrine. Texto escuro. (Era claro enquanto o\n  // fundo era o pátio de asfalto; trocar a imagem sem trocar isto deixa texto\n  // branco sobre concreto claro, ilegível.)\n  const dark = false;\n  // fundo escuro: branco puro + sombra pra legibilidade; claro: cinza-grafite\n  // O KM era #6f6f74 — cinza médio sobre concreto médio, contraste ~2,6:1, a\n  // linha sumia. Vira grafite, um passo abaixo do preço: a hierarquia entre as\n  // duas linhas passa a vir do CORPO (48px/300 contra 24px/500), não de apagar\n  // a de baixo até ela não ser mais lida.\n  const tx = dark\n    ? { preco: '#ffffff', km: '#dfe0e6', bullet: '#ffffff', icone: '#f1f1f5' }\n    : { preco: '#2b2b31', km: '#3d3d44', bullet: '#141416', icone: '#1a1a1c' };\n  if(dark){ ctx.shadowColor = 'rgba(0,0,0,.55)'; ctx.shadowBlur = 8; ctx.shadowOffsetY = 1; }\n\n  // Preço e KM caem sobre a FOTO, e o chão dela muda a cada veículo: asfalto\n  // escuro no G 63, concreto claro na McLaren. Só a cor não resolve — o mesmo\n  // grafite que lê bem no claro afunda no escuro. O halo claro dá a borda que\n  // falta nos dois casos, e é limpo logo depois: se ficasse ligado, vazaria\n  // para os destaques e para o carro recortado, que é redesenhado no fim.\n  if(!dark){ ctx.shadowColor = 'rgba(255,255,255,.45)'; ctx.shadowBlur = 10; ctx.shadowOffsetY = 0; }\n\n  // Peso 400 no claro (era 300): em 48px a haste do 300 é fina demais, o halo\n  // comia metade dela e o preço saía MAIS FRACO que o KM logo abaixo — a\n  // hierarquia invertida, com o número que mais importa sendo o que menos lê.\n  const preco = val('preco').replace(/^R\\$\\s*/i, '');\n  if(preco) spacedText('R$ ' + preco, W/2, PISO_TOP + 54, '400 48px Montserrat, sans-serif', 10, tx.preco);\n\n  const kmParts = [];\n  if(val('km')) kmParts.push(val('km') + ' KM');\n  if(val('kmextra')) kmParts.push(val('kmextra').toUpperCase());\n  if(kmParts.length)\n    spacedText(kmParts.join('  |  '), W/2, PISO_TOP + 102, (dark ? '600' : '500') + ' 24px Montserrat, sans-serif', 5, tx.km);\n\n  if(!dark){ ctx.shadowColor = 'transparent'; ctx.shadowBlur = 0; }\n\n  // Máximo 3 destaques, UMA linha cada: a fonte encolhe até caber (mín. 25px)\n  // e em último caso o texto é cortado com \"…\" — nunca quebra de linha.\n  const bullets = ['b1','b2','b3'].map(val).filter(Boolean);\n  const textX = 208, maxW = 800, lineH = FEED ? 42 : 44;\n  const areaTop = PISO_TOP + 156, areaBot = Math.min(DIAG_L, DIAG_R) - (FEED ? 20 : 26);\n  const items = bullets.map(b => {\n    let size = 34;\n    ctx.font = `700 ${size}px Montserrat, sans-serif`;\n    while(size > 25 && ctx.measureText(b).width > maxW){\n      size -= 1;\n      ctx.font = `700 ${size}px Montserrat, sans-serif`;\n    }\n    let text = b;\n    while(text.length > 4 && ctx.measureText(text + '…').width > maxW)\n      text = text.slice(0, -1).trimEnd();\n    if(text !== b) text += '…';\n    return { text, size };\n  });\n  let gap = 30;\n  if(items.length > 1)\n    gap = Math.max(FEED ? 16 : 20, Math.min(48, (areaBot - areaTop - items.length*lineH) / (items.length - 1)));\n  const totalH = items.length*lineH + gap*Math.max(0, items.length-1);\n  let by = areaTop + Math.max(0, (areaBot - areaTop - totalH)/2) + 30;\n\n  for(const it of items){\n    const iy = by - 11;\n    ctx.strokeStyle = tx.icone; ctx.lineWidth = 3.5;\n    ctx.beginPath(); ctx.arc(158, iy, 16, 0, Math.PI*2); ctx.stroke();\n    ctx.fillStyle = tx.icone;\n    ctx.beginPath(); ctx.arc(158, iy, 7.5, 0, Math.PI*2); ctx.fill();\n    ctx.font = `700 ${it.size}px Montserrat, sans-serif`; ctx.fillStyle = tx.bullet;\n    ctx.fillText(it.text, textX, by);\n    by += lineH + gap;\n  }\n\n  // O veículo é redesenhado por ÚLTIMO — prioridade máxima na peça.\n  // Com o slider vertical livre, carro e texto podem se encontrar nos\n  // extremos; nesse encontro quem fica por cima é sempre o carro.\n  if(comRecorte && posCarro){\n    ctx.save();\n    ctx.beginPath(); ctx.rect(0, 540, W, H - 540); ctx.clip();\n    ctx.drawImage(state.foto1Cut, posCarro.dx, posCarro.dy, posCarro.dw, posCarro.dh);\n    ctx.restore();\n  }\n\n  ctx.shadowColor = 'transparent'; ctx.shadowBlur = 0; ctx.shadowOffsetY = 0;\n\n  if(!FEED){ // faixa da foto de baixo: só no Stories\n  ctx.save();\n  ctx.beginPath();\n  ctx.moveTo(0, DIAG_L); ctx.lineTo(W, DIAG_R);\n  ctx.lineTo(W, H); ctx.lineTo(0, H);\n  ctx.closePath(); ctx.clip();\n  if(state.foto2){\n    // A faixa é sempre preenchida por inteiro (sem sobras, sem blur).\n    // Foto mais alta que a faixa: âncora automática na BASE da foto —\n    // as rodas nunca cortam; sai céu/fundo por cima. Se o usuário mexer\n    // no slider de posição da Foto 2, o valor dele prevalece.\n    const bw = W, bh = H - DIAG_R;\n    const cover = Math.max(bw/state.foto2.width, bh/state.foto2.height);\n    const dh = state.foto2.height * cover * (state.f2.zoom || 1);\n    let opt = state.f2;\n    if(dh > bh * 1.15 && state.f2.y === .5){\n      const rangeY = Math.max(dh - bh, bh*.6);\n      opt = {...state.f2, y: .5 + (dh - bh) / (2 * rangeY)};\n    }\n    drawPhoto(state.foto2, 0, DIAG_R - 2, bw, bh + 2, opt);\n  }\n  else placeholder(0, DIAG_R, W, H - DIAG_R, 'FOTO TRASEIRA / LATERAL');\n\n  // sombra de acomodação: o piso projeta penumbra suave no topo da foto\n  // (só nos pisos de textura; no pérola a divisa limpa é a estética)\n  { // acomodação da base em todos os pisos (agora todos texturizados)\n    const acomA = (state.pisoTipo === 'asfalto') ? .42 : .22;\n    g = ctx.createLinearGradient(0, DIAG_R - 2, 0, DIAG_L + 78);\n    g.addColorStop(0, `rgba(0,0,0,${acomA})`);\n    g.addColorStop(.55, `rgba(0,0,0,${acomA * .38})`);\n    g.addColorStop(1, 'rgba(0,0,0,0)');\n    ctx.fillStyle = g;\n    ctx.fillRect(0, DIAG_R - 2, W, DIAG_L - DIAG_R + 82);\n  }\n\n  ctx.restore();\n  } // fim da faixa da foto de baixo\n}\n\n/* ================================================================\n   TIPO 1 — CLÁSSICO (original, em produção)\n   ----------------------------------------------------------------\n   Desenho aprovado e em uso. O texto vive sobre uma FAIXA DE PISO\n   PINTADA (`pisoImgs`), com PISO_TOP fixo em 1000 e a paleta derivada\n   do piso escolhido (`dark = piso === 'asfalto'`) — por isso o fundo\n   sob o preço é conhecido e o contraste não depende da foto.\n\n   O Clássico Loja abaixo trocou essa faixa pelo chão da própria foto\n   de fundo. Ganhou continuidade e perdeu o controle do contraste: no\n   G 63, com o carro em piso escuro, o preço mediu 1,00:1 contra a\n   fachada. É por isso que os dois convivem em vez de um substituir o\n   outro — este continua sendo o padrão até o novo ser validado.\n================================================================ */\nfunction renderClassicoOriginal(){\n  const FEED = H === H_FEED;   // 1080×1350: só a foto principal, rodapé fecha mais cedo\n  const PHOTO1_H = 1000;\n\n  // fachada da loja como fundo do topo — o letreiro ATTRA é o logo\n  ctx.save();\n  ctx.beginPath(); ctx.rect(0, 0, W, PHOTO1_H); ctx.clip();\n  if(facadeClassicoImg.complete && facadeClassicoImg.naturalWidth){\n    // -60px esconde o toldo; escala 1.06 ancorada à esquerda desloca o\n    // conteúdo pra direita (letreiro ~+16px vs 1.03) mantendo o full-bleed:\n    // borda esquerda fixa em 0, sobra recortada só à direita\n    const fw = W * 1.06;\n    ctx.drawImage(facadeClassicoImg, 0, -60, fw, facadeClassicoImg.height * (fw/facadeClassicoImg.width));\n  } else {\n    ctx.fillStyle = '#101013'; ctx.fillRect(0, 0, W, PHOTO1_H);\n  }\n  // (piso da fachada tratado direto na imagem editada — sem overlay)\n  ctx.restore();\n\n  // foto do carro com bordas esfumadas, fundida na fachada\n  let topGap = PHOTO1_H;\n  if(state.foto1){\n    topGap = Math.max(0, drawPhotoFeather(state.foto1, 0, 0, W, PHOTO1_H, state.f1));\n  } else {\n    ctx.fillStyle = 'rgba(255,255,255,.45)';\n    ctx.font = '600 26px Montserrat, sans-serif';\n    ctx.textAlign = 'center';\n    ctx.fillText('ENVIE A FOTO PRINCIPAL DO VEÍCULO', W/2, 750);\n    ctx.textAlign = 'left';\n  }\n\n  // gradiente p/ legibilidade do título\n  let g;\n  if(topGap < 150){\n    // foto cobre o letreiro (ex.: foto vertical ou zoom alto) — comportamento antigo\n    g = ctx.createLinearGradient(0, 0, 0, 760);\n    g.addColorStop(0, 'rgba(0,0,0,.62)');\n    g.addColorStop(.55, 'rgba(0,0,0,.28)');\n    g.addColorStop(1, 'rgba(0,0,0,0)');\n    ctx.fillStyle = g; ctx.fillRect(0, 0, W, 760);\n  } else {\n    // preserva o brilho do letreiro; escurece só a área do título\n    g = ctx.createLinearGradient(0, 170, 0, 780);\n    g.addColorStop(0, 'rgba(0,0,0,0)');\n    g.addColorStop(.22, 'rgba(0,0,0,.60)');\n    g.addColorStop(.48, 'rgba(0,0,0,.48)');\n    g.addColorStop(.75, 'rgba(0,0,0,.22)');\n    g.addColorStop(1, 'rgba(0,0,0,0)');\n    ctx.fillStyle = g; ctx.fillRect(0, 170, W, 610);\n  }\n\n\n\n  // logo desenhado só quando a foto cobre o letreiro da fachada\n  if(topGap < 150) drawLogoWhite(W/2, 168, 340);\n\n  const marca  = val('marca').toUpperCase();\n  const modelo = val('modelo').toUpperCase();\n  const ano    = val('ano');\n\n  // sombra suave para o título não se perder no fundo da fachada/foto\n  ctx.save();\n  ctx.shadowColor = 'rgba(0,0,0,.85)';\n  ctx.shadowBlur = 30;\n  ctx.shadowOffsetY = 3;\n\n  if(marca) spacedText(marca, W/2, 316, '600 30px Montserrat, sans-serif', 11, '#ffffff');\n\n  let msize = 92, mspace = 26;\n  while(msize > 40 && spacedWidth(modelo, `200 ${msize}px Montserrat, sans-serif`, mspace) > 980){\n    msize -= 3; mspace = Math.max(8, mspace - 1);\n  }\n  if(modelo) spacedText(modelo, W/2, 400, `200 ${msize}px Montserrat, sans-serif`, mspace, '#ffffff');\n\n  if(ano){\n    const yy = 458;\n    const tw = spacedText(ano, W/2, yy, '300 34px Montserrat, sans-serif', 15, '#ffffff');\n    ctx.strokeStyle = 'rgba(255,255,255,.85)'; ctx.lineWidth = 1.5;\n    ctx.beginPath();\n    ctx.moveTo(W/2 - tw/2 - 195, yy - 11); ctx.lineTo(W/2 - tw/2 - 40, yy - 11);\n    ctx.moveTo(W/2 + tw/2 + 40,  yy - 11); ctx.lineTo(W/2 + tw/2 + 195, yy - 11);\n    ctx.stroke();\n  }\n\n  ctx.restore(); // fim da sombra do título\n\n  // corte transversal ajustável (slider): positivo sobe, negativo desce\n  const corte = parseInt($('corte').value, 10) || 0;\n  // Feed 4:5: não há foto de baixo — o piso vai até a borda, sem diagonal.\n  const CUT = FEED ? H : 1416 - corte;\n  // diagonal de volta (assinatura do layout): 40px de inclinação\n  const DIAG_L = FEED ? H : CUT + 20, DIAG_R = FEED ? H : CUT - 20;\n  const areaPath = () => {\n    ctx.beginPath();\n    ctx.moveTo(0, PISO_TOP); ctx.lineTo(W, PISO_TOP);\n    ctx.lineTo(W, DIAG_R); ctx.lineTo(0, DIAG_L);\n    ctx.closePath();\n  };\n\n  // Fundo da área de texto: Pérola (sólido), Concreto ou Asfalto\n  // (texturas reais fundidas dentro da foto por máscara de alpha).\n  const piso = state.pisoTipo || 'perola';\n  // sem fusão no topo: a dissolvência de 56px invadia as rodas em carros\n  // baixos. A divisa fica seca e a continuidade vem do véu (abaixo), como no\n  // tratamento manual do Photoshop.\n  const FUSAO_H = 0;\n  // altura da divisa ajustável: posicionar SEMPRE abaixo do veículo\n  const pisoShift = parseInt($('pisoy').value, 10) || 0;\n  // Feed: o bloco de texto (preço, KM, 3 destaques) precisa de ~340px até a\n  // borda — o slider do piso não pode empurrá-lo para fora da peça.\n  const PISO_TOP = FEED ? Math.min(PHOTO1_H + pisoShift, H - 340) : PHOTO1_H + pisoShift;\n\n  {\n    // Pérola/Concreto/Asfalto = piso texturizado REAL (imagem embutida).\n    // Pérola reusa a textura do concreto com um véu pérola por cima: clareia\n    // até um tom pérola limpo mantendo o grão real — como piso polido do Photoshop.\n    const img = pisoImgs[piso === 'perola' ? 'concreto' : piso];\n    // overlap dentro da foto = tamanho da máscara → textura chega 100% opaca na divisa\n    const bandTop = PISO_TOP - FUSAO_H;\n    const bandH = DIAG_L - bandTop;\n    ctx.save();\n    ctx.beginPath();\n    ctx.moveTo(0, bandTop); ctx.lineTo(W, bandTop);\n    ctx.lineTo(W, DIAG_R); ctx.lineTo(0, DIAG_L);\n    ctx.closePath(); ctx.clip();\n    if(img && img.complete && img.naturalWidth){\n      const osc = document.createElement('canvas');\n      osc.width = W; osc.height = bandH;\n      const ox = osc.getContext('2d');\n      const ps = Math.max(W / img.width, bandH / img.height);\n      ox.drawImage(img, (W - img.width*ps)/2, (bandH - img.height*ps)/2,\n                   img.width*ps, img.height*ps);\n      ctx.drawImage(osc, 0, bandTop);\n    } else {\n      ctx.fillStyle = piso === 'asfalto' ? '#3a3a3c' : (piso === 'perola' ? '#eef1f2' : '#eceeed');\n      ctx.fillRect(0, bandTop, W, bandH);\n    }\n    // véu pérola: clareia a textura do concreto até o tom pérola, sem perder o grão\n    if(piso === 'perola'){\n      // fade-in do véu na zona de fusão (bandTop..PISO_TOP) → sem divisa nítida\n      // Continuidade: o véu entra no MESMO tom em que o da foto terminou\n      // (.42) e encorpa piso adentro, então não há degrau na divisa.\n      const veu = ctx.createLinearGradient(0, bandTop, 0, DIAG_L);\n      veu.addColorStop(0, 'rgba(246,248,249,.42)');\n      veu.addColorStop(Math.min(1, 160/bandH), 'rgba(246,248,249,.78)');\n      veu.addColorStop(1, 'rgba(236,240,242,.68)');\n      ctx.fillStyle = veu; ctx.fillRect(0, bandTop, W, bandH);\n    }\n    // sombras internas discretas (intensidade conforme o tom do piso)\n    const sa = piso === 'asfalto' ? .14 : .07;\n    const sombraTopo = ctx.createLinearGradient(0, PISO_TOP, 0, PISO_TOP + 160);\n    sombraTopo.addColorStop(0, `rgba(0,0,0,${sa})`);\n    sombraTopo.addColorStop(1, 'rgba(0,0,0,0)');\n    ctx.fillStyle = sombraTopo; ctx.fillRect(0, PISO_TOP, W, 160);\n    const sombraBase = ctx.createLinearGradient(0, CUT - 160, 0, CUT);\n    sombraBase.addColorStop(0, 'rgba(0,0,0,0)');\n    sombraBase.addColorStop(1, `rgba(0,0,0,${sa})`);\n    ctx.fillStyle = sombraBase; ctx.fillRect(0, CUT - 160, W, DIAG_L - (CUT - 160));\n    ctx.restore();\n  }\n\n  // SEM véu sobre a foto.\n  //\n  // Havia aqui um degradê branco (até 42% de opacidade) pintado sobre os\n  // ÚLTIMOS 110px DA FOTO, para a passagem foto→piso não ler como linha dura.\n  // O custo era alto demais: essa faixa é justamente onde ficam os pneus e o\n  // chão sob o carro, e o véu lavava a borracha e a sombra de contato — o carro\n  // parecia flutuar. A divisa seca é preferível a estragar o veículo, que é o\n  // assunto da peça. (A fusão do topo do piso já era 0 pelo mesmo motivo.)\n\n  // paleta dos textos conforme o fundo\n  const dark = piso === 'asfalto';\n  // fundo escuro: branco puro + sombra pra legibilidade; claro: cinza-grafite\n  const tx = dark\n    ? { preco: '#ffffff', km: '#dfe0e6', bullet: '#ffffff', icone: '#f1f1f5' }\n    : { preco: '#35353b', km: '#6f6f74', bullet: '#141416', icone: '#1a1a1c' };\n  if(dark){ ctx.shadowColor = 'rgba(0,0,0,.55)'; ctx.shadowBlur = 8; ctx.shadowOffsetY = 1; }\n\n  const preco = val('preco').replace(/^R\\$\\s*/i, '');\n  if(preco) spacedText('R$ ' + preco, W/2, PISO_TOP + (FEED ? 54 : 62), (dark ? '400' : '300') + ' 48px Montserrat, sans-serif', 10, tx.preco);\n\n  const kmParts = [];\n  if(val('km')) kmParts.push(val('km') + ' KM');\n  if(val('kmextra')) kmParts.push(val('kmextra').toUpperCase());\n  if(kmParts.length)\n    spacedText(kmParts.join('  |  '), W/2, PISO_TOP + (FEED ? 102 : 118), (dark ? '600' : '500') + ' 24px Montserrat, sans-serif', 5, tx.km);\n\n  // Máximo 3 destaques, UMA linha cada: a fonte encolhe até caber (mín. 25px)\n  // e em último caso o texto é cortado com \"…\" — nunca quebra de linha.\n  const bullets = ['b1','b2','b3'].map(val).filter(Boolean);\n  const textX = 208, maxW = 800, lineH = FEED ? 42 : 44;\n  const areaTop = PISO_TOP + (FEED ? 150 : 188), areaBot = Math.min(DIAG_L, DIAG_R) - 26;\n  const items = bullets.map(b => {\n    let size = 34;\n    ctx.font = `700 ${size}px Montserrat, sans-serif`;\n    while(size > 25 && ctx.measureText(b).width > maxW){\n      size -= 1;\n      ctx.font = `700 ${size}px Montserrat, sans-serif`;\n    }\n    let text = b;\n    while(text.length > 4 && ctx.measureText(text + '…').width > maxW)\n      text = text.slice(0, -1).trimEnd();\n    if(text !== b) text += '…';\n    return { text, size };\n  });\n  let gap = 30;\n  if(items.length > 1)\n    gap = Math.max(20, Math.min(48, (areaBot - areaTop - items.length*lineH) / (items.length - 1)));\n  const totalH = items.length*lineH + gap*Math.max(0, items.length-1);\n  let by = areaTop + Math.max(0, (areaBot - areaTop - totalH)/2) + 30;\n\n  for(const it of items){\n    const iy = by - 11;\n    ctx.strokeStyle = tx.icone; ctx.lineWidth = 3.5;\n    ctx.beginPath(); ctx.arc(158, iy, 16, 0, Math.PI*2); ctx.stroke();\n    ctx.fillStyle = tx.icone;\n    ctx.beginPath(); ctx.arc(158, iy, 7.5, 0, Math.PI*2); ctx.fill();\n    ctx.font = `700 ${it.size}px Montserrat, sans-serif`; ctx.fillStyle = tx.bullet;\n    ctx.fillText(it.text, textX, by);\n    by += lineH + gap;\n  }\n  ctx.shadowColor = 'transparent'; ctx.shadowBlur = 0; ctx.shadowOffsetY = 0;\n\n  if(!FEED){ // faixa da foto de baixo: só no Stories\n  ctx.save();\n  ctx.beginPath();\n  ctx.moveTo(0, DIAG_L); ctx.lineTo(W, DIAG_R);\n  ctx.lineTo(W, H); ctx.lineTo(0, H);\n  ctx.closePath(); ctx.clip();\n  if(state.foto2){\n    // A faixa é sempre preenchida por inteiro (sem sobras, sem blur).\n    // Foto mais alta que a faixa: âncora automática na BASE da foto —\n    // as rodas nunca cortam; sai céu/fundo por cima. Se o usuário mexer\n    // no slider de posição da Foto 2, o valor dele prevalece.\n    const bw = W, bh = H - DIAG_R;\n    const cover = Math.max(bw/state.foto2.width, bh/state.foto2.height);\n    const dh = state.foto2.height * cover * (state.f2.zoom || 1);\n    let opt = state.f2;\n    if(dh > bh * 1.15 && state.f2.y === .5){\n      const rangeY = Math.max(dh - bh, bh*.6);\n      opt = {...state.f2, y: .5 + (dh - bh) / (2 * rangeY)};\n    }\n    drawPhoto(state.foto2, 0, DIAG_R - 2, bw, bh + 2, opt);\n  }\n  else placeholder(0, DIAG_R, W, H - DIAG_R, 'FOTO TRASEIRA / LATERAL');\n\n  // sombra de acomodação: o piso projeta penumbra suave no topo da foto\n  // (só nos pisos de textura; no pérola a divisa limpa é a estética)\n  { // acomodação da base em todos os pisos (agora todos texturizados)\n    const acomA = (state.pisoTipo === 'asfalto') ? .42 : .22;\n    g = ctx.createLinearGradient(0, DIAG_R - 2, 0, DIAG_L + 78);\n    g.addColorStop(0, `rgba(0,0,0,${acomA})`);\n    g.addColorStop(.55, `rgba(0,0,0,${acomA * .38})`);\n    g.addColorStop(1, 'rgba(0,0,0,0)');\n    ctx.fillStyle = g;\n    ctx.fillRect(0, DIAG_R - 2, W, DIAG_L - DIAG_R + 82);\n  }\n\n  ctx.restore();\n  } // fim da faixa da foto de baixo\n}\n\n/* ================================================================\n   TIPO 2 — DESTAQUE (claro, ficha técnica, foto em card)\n================================================================ */\nfunction renderDestaque(){\n  const FEED = H === H_FEED;   // 1080×1350: só a foto principal, rodapé fecha mais cedo\n  // fundo claro\n  let g = ctx.createLinearGradient(0, 0, 0, H);\n  g.addColorStop(0, '#ffffff'); g.addColorStop(1, '#ededf0');\n  ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);\n\n  // logo preta no topo + filete vermelho\n  drawLogoBlack(W/2, 130, 330);\n  ctx.fillStyle = RED; ctx.fillRect(0, 232, W, 4);\n\n  const marca  = val('marca').toUpperCase();\n  const modelo = val('modelo').toUpperCase();\n\n  if(marca){\n    const tw = spacedText(marca, W/2, 322, 'italic 600 34px Montserrat, sans-serif', 8, '#1b1b1e');\n    ctx.strokeStyle = '#1b1b1e'; ctx.lineWidth = 2;\n    ctx.beginPath();\n    ctx.moveTo(W/2 - tw/2 - 140, 310); ctx.lineTo(W/2 - tw/2 - 30, 310);\n    ctx.moveTo(W/2 + tw/2 + 30, 310);  ctx.lineTo(W/2 + tw/2 + 140, 310);\n    ctx.stroke();\n  }\n\n  let msize = 76;\n  while(msize > 36 && spacedWidth(modelo, `800 ${msize}px Montserrat, sans-serif`, 6) > 940) msize -= 3;\n  if(modelo) spacedText(modelo, W/2, 424, `800 ${msize}px Montserrat, sans-serif`, 6, '#111114');\n\n  const anokm = [val('ano'), val('km') ? val('km') + ' KM' : ''].filter(Boolean).join('  ·  ');\n  if(anokm) spacedText(anokm, W/2, 482, 'italic 500 32px Montserrat, sans-serif', 4, '#55555a');\n\n  // preço sóbrio (texto simples, sem pílula)\n  const preco = val('preco').replace(/^R\\$\\s*/i, '');\n  if(preco) spacedText('R$ ' + preco, W/2, 556, '700 48px Montserrat, sans-serif', 3, '#1b1b1e');\n\n  // pílulas com os diferenciais do carro (o verdadeiro destaque)\n  const chips = val('selo').split(',').map(s => s.trim().toUpperCase()).filter(Boolean).slice(0, 4);\n  if(chips.length){\n    const font = s => `italic 700 ${s}px Montserrat, sans-serif`;\n    let fsize = 27;\n    const totalW = s => {\n      ctx.font = font(s);\n      return chips.reduce((a, c) => a + ctx.measureText(c).width + 60, 0) + (chips.length-1)*16;\n    };\n    while(fsize > 17 && totalW(fsize) > 950) fsize -= 1;\n    ctx.font = font(fsize);\n    const widths = chips.map(c => ctx.measureText(c).width + 60);\n    const total = widths.reduce((a, b) => a + b, 0) + (chips.length-1)*16;\n    let x = W/2 - total/2;\n    const ph = Math.round(fsize*2.15), py = 604;\n    chips.forEach((c, i) => {\n      ctx.fillStyle = RED;\n      rr(x, py, widths[i], ph, ph/2); ctx.fill();\n      ctx.fillStyle = '#ffffff';\n      ctx.font = font(fsize);\n      ctx.textAlign = 'center';\n      ctx.fillText(c, x + widths[i]/2, py + ph/2 + fsize*.36);\n      ctx.textAlign = 'left';\n      x += widths[i] + 16;\n    });\n  }\n\n  // card da foto principal (foto inteira, sem recorte de fundo)\n  // Feed: o card fecha a peça (não há tira de fotos embaixo).\n  const cx0 = 90, cy0 = 706, cw = 900, ch = FEED ? H - 706 - 64 : 636;\n  ctx.save();\n  ctx.shadowColor = 'rgba(0,0,0,.20)'; ctx.shadowBlur = 32; ctx.shadowOffsetY = 12;\n  ctx.fillStyle = '#fff';\n  rr(cx0, cy0, cw, ch, 26); ctx.fill();\n  ctx.restore();\n  ctx.save();\n  rr(cx0, cy0, cw, ch, 26); ctx.clip();\n  if(state.foto1) drawPhoto(state.foto1, cx0, cy0, cw, ch, state.f1);\n  else placeholder(cx0, cy0, cw, ch, 'FOTO DO VEÍCULO', false);\n  ctx.restore();\n\n  // rodapé com 1 a 3 fotos (o layout se ajusta sozinho) — só no Stories\n  if(FEED) return;\n  const bots = [state.foto2, state.foto3, state.foto4].filter(Boolean);\n  const py0 = 1412, phh = H - py0;\n  ctx.fillStyle = RED; ctx.fillRect(0, py0 - 5, W, 5);\n  if(!bots.length){\n    placeholder(0, py0, W, phh, 'FOTOS DE BAIXO (1 OU 3)', false);\n  } else if(bots.length === 1){\n    drawPhoto(bots[0], 0, py0, W, phh, state.f2);\n  } else {\n    const gap = 6, colW = (W - gap*(bots.length - 1)) / bots.length;\n    bots.forEach((img, i) => {\n      drawPhoto(img, Math.round(i*(colW+gap)), py0, Math.round(colW), phh,\n                i === 0 ? state.f2 : undefined);\n    });\n  }\n}\n\n/* ================================================================\n   TIPO 3 — ESTOQUE (lista de até 4 carros)\n================================================================ */\nfunction renderEstoque(){\n  const FEED = H === H_FEED;   // 1080×1350: só a foto principal, rodapé fecha mais cedo\n  // fundo\n  let g = ctx.createLinearGradient(0, 0, 0, H);\n  g.addColorStop(0, '#efefef'); g.addColorStop(1, '#dfdfe2');\n  ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);\n\n  // linhas retas diagonais, ancoradas na geometria do logo\n  // (mesma inclinação da faixa vermelha do \"A\": ~0.4)\n  const m = 0.4;\n  const diag = (c, color, wdt, x0, x1) => {\n    ctx.strokeStyle = color; ctx.lineWidth = wdt; ctx.lineCap = 'butt';\n    ctx.beginPath();\n    ctx.moveTo(x0, m*x0 + c); ctx.lineTo(x1, m*x1 + c);\n    ctx.stroke();\n  };\n  // canto superior direito\n  diag(-330, RED, 18, 700, 1120);\n  diag(-376, '#2a2a2f', 13, 800, 1120);\n  diag(-422, '#b9b9be', 9, 900, 1120);\n  // canto inferior esquerdo (eco discreto) — ancorado na base da peça\n  const dz = H - H_STORIES;\n  diag(1806 + dz, RED, 18, -40, 320);\n  diag(1852 + dz, '#2a2a2f', 13, -40, 220);\n  diag(1898 + dz, '#b9b9be', 9, -40, 120);\n\n  // título\n  const t1 = val('et1').toUpperCase(), t2 = val('et2').toUpperCase();\n  ctx.textAlign = 'left';\n  ctx.font = 'italic 900 92px Montserrat, sans-serif';\n  ctx.fillStyle = '#161619';\n  if(t1) ctx.fillText(t1, 80, 200);\n  ctx.fillStyle = RED;\n  if(t2) ctx.fillText(t2, 80, 308);\n\n  // carros preenchidos\n  const cars = [];\n  for(let i = 0; i < 4; i++){\n    const nome = val('e_nome'+i);\n    if(nome || state.estFotos[i])\n      cars.push({nome, ano: val('e_ano'+i), km: val('e_km'+i),\n                 preco: val('e_preco'+i), tag: val('e_tag'+i), foto: state.estFotos[i]});\n  }\n  if(!cars.length){\n    ctx.fillStyle = 'rgba(0,0,0,.35)';\n    ctx.font = '600 30px Montserrat, sans-serif';\n    ctx.textAlign = 'center';\n    ctx.fillText('PREENCHA OS CARROS DA LISTA', W/2, 900);\n    ctx.textAlign = 'left';\n  }\n\n  // Feed: os mesmos 4 cards, mais baixos, com os textos em ~74%.\n  const areaTop = 400, areaBot = FEED ? H - 110 : 1770;\n  const rowH = Math.min(372, (areaBot - areaTop) / Math.max(cars.length, 1));\n  const blockTop = areaTop + Math.max(0, (areaBot - areaTop - rowH*cars.length)/2);\n  const cardX = 60, cardW = 960;\n\n  cars.forEach((car, i) => {\n    const cardY = blockTop + i*rowH + 16;\n    const cardH = rowH - 32;\n    // janela de largura FIXA em todos os cards — grade alinhada; a foto\n    // preenche por cover (corta sobra em vez de desalinhar as colunas)\n    const photoW = Math.round(cardH * 1.5);\n\n    // card branco de linha inteira\n    ctx.save();\n    ctx.shadowColor = 'rgba(0,0,0,.10)'; ctx.shadowBlur = 26; ctx.shadowOffsetY = 8;\n    ctx.fillStyle = '#ffffff';\n    rr(cardX, cardY, cardW, cardH, 22); ctx.fill();\n    ctx.restore();\n\n    // foto à esquerda (cover — janela uniforme)\n    ctx.save();\n    rr(cardX, cardY, cardW, cardH, 22); ctx.clip();\n    ctx.beginPath(); ctx.rect(cardX, cardY, photoW, cardH); ctx.clip();\n    if(car.foto) drawPhoto(car.foto, cardX, cardY, photoW, cardH);\n    else placeholder(cardX, cardY, photoW, cardH, 'FOTO', false);\n    ctx.restore();\n\n    // chip discreto sobre a foto\n    if(car.tag){\n      const cFont = '700 21px Montserrat, sans-serif';\n      ctx.font = cFont;\n      const tw = ctx.measureText(car.tag.toUpperCase()).width;\n      ctx.fillStyle = RED;\n      rr(cardX + 16, cardY + 16, tw + 36, 38, 9); ctx.fill();\n      ctx.fillStyle = '#ffffff';\n      ctx.fillText(car.tag.toUpperCase(), cardX + 34, cardY + 43);\n    }\n\n    // textos à direita — a fonte do nome diminui sozinha p/ nunca cortar\n    const textX = cardX + photoW + 42;\n    const textW = cardX + cardW - textX - 36;\n    let nf = FEED ? 30 : 41, nomeFont, nomeLines;\n    while(true){\n      nomeFont = `700 ${nf}px Montserrat, sans-serif`;\n      nomeLines = wrapLines(car.nome.toUpperCase(), nomeFont, textW);\n      if(nomeLines.length <= 2 || nf <= (FEED ? 22 : 29)) break;\n      nf -= 2;\n    }\n    // evita linha órfã (uma palavrinha sozinha na 2ª linha)\n    if(nomeLines.length === 2 && nomeLines[1].length <= 4){\n      for(let t = nf - 2; t >= (FEED ? 22 : 30); t -= 2){\n        const tf = `700 ${t}px Montserrat, sans-serif`;\n        const tl = wrapLines(car.nome.toUpperCase(), tf, textW);\n        if(tl.length === 1){ nf = t; nomeFont = tf; nomeLines = tl; break; }\n      }\n    }\n    nomeLines = nomeLines.slice(0, 3);\n    const nameLH = nf + 9;\n    const anokm = [car.ano, car.km ? (car.km.toUpperCase().includes('KM') ? car.km.toUpperCase() : car.km + ' KM') : '']\n      .filter(Boolean).join('  ·  ');\n    const infoH = nomeLines.length*nameLH + (anokm ? (FEED ? 34 : 46) : 0) + (car.preco ? (FEED ? 44 : 58) : 0);\n    let ty = cardY + Math.max(24, (cardH - infoH)/2) + nf*.82;\n    ctx.font = nomeFont; ctx.fillStyle = '#17181b';\n    nomeLines.forEach(l => { ctx.fillText(l, textX, ty); ty += nameLH; });\n    if(anokm){\n      ty += 6;\n      ctx.font = `500 ${FEED ? 22 : 29}px Montserrat, sans-serif`; ctx.fillStyle = '#7a7a81';\n      ctx.fillText(anokm, textX, ty);\n      ty += FEED ? 44 : 58;\n    } else ty += 12;\n    if(car.preco){\n      ctx.font = `800 ${FEED ? 31 : 40}px Montserrat, sans-serif`; ctx.fillStyle = RED;\n      ctx.fillText('R$ ' + car.preco, textX, ty);\n    }\n  });\n\n  // logo preta no rodapé\n  drawLogoBlack(W/2, H - 72, 250);\n}\n\n/* ---------- RENDER (dispatch) ---------- */\n/* ================================================================\n   TIPO 4 — EDITORIAL (premium, integrado à foto — referência: layouts\n   de importadoras de luxo em que a foto full-bleed escurece na base e\n   vira a área de informação; funciona com QUALQUER foto, sem recorte\n   de fundo)\n================================================================ */\nconst ED = {\n  fonte: \"'Inter', 'Helvetica Neue', Helvetica, Arial, sans-serif\",\n};\n\nfunction edTextoEsq(text, x, y, font, spacing, color){\n  ctx.font = font; ctx.fillStyle = color; ctx.textBaseline = 'alphabetic';\n  let cx = x;\n  for(const ch of [...text]){\n    ctx.fillText(ch, cx, y);\n    cx += ctx.measureText(ch).width + spacing;\n  }\n  return cx - spacing - x;\n}\n\nfunction edTextoCentro(text, cx, y, font, spacing, color){\n  ctx.font = font; ctx.fillStyle = color; ctx.textBaseline = 'alphabetic';\n  const chars = [...text];\n  let total = 0;\n  for(const ch of chars) total += ctx.measureText(ch).width + spacing;\n  total -= spacing;\n  let x = cx - total/2;\n  for(const ch of chars){\n    ctx.fillText(ch, x, y);\n    x += ctx.measureText(ch).width + spacing;\n  }\n}\n\nfunction renderEditorial(){\n  const FEED = H === H_FEED;   // 1080×1350: só a foto principal, rodapé fecha mais cedo\n  // ---------- cenário de estúdio (palco elevado) ----------\n  if(edFundoImg.complete && edFundoImg.naturalWidth){\n    // Feed: o cenário entra na altura do Stories, deslocado para cima, para o\n    // piso do palco cair onde o carro pousa (e não esticar as barras de luz).\n    if(FEED) ctx.drawImage(edFundoImg, 0, -342, W, H_STORIES);\n    else ctx.drawImage(edFundoImg, 0, 0, W, H);\n  } else {\n    ctx.fillStyle = '#121317'; ctx.fillRect(0, 0, W, H);\n  }\n\n  // ---------- topo: sombreamento suave (as barras de luz não ofuscam\n  // a logo) + logo maior ----------\n  const topo = ctx.createLinearGradient(0, 0, 0, 420);\n  topo.addColorStop(0, 'rgba(0,0,0,.85)');\n  topo.addColorStop(.55, 'rgba(0,0,0,.45)');\n  topo.addColorStop(1, 'rgba(0,0,0,0)');\n  ctx.fillStyle = topo; ctx.fillRect(0, 0, W, 420);\n  drawLogoWhite(W/2, 128, 250);\n\n  // ---------- carro (recortado pela IA) no palco ----------\n  const carro = state.foto1Cut || state.foto1;\n  if(carro){\n    const bx = 30, bw = W - 60, by = FEED ? 280 : 340, bh = FEED ? 760 : 1080;\n    const base = Math.min(bw/carro.width, bh/carro.height);\n    const sc = base * (state.f1.zoom || 1);\n    const dw = carro.width * sc, dh = carro.height * sc;\n    const dx = bx + (bw - dw)/2 + (state.f1.x - .5) * bw * .8;\n    const dy = by + (bh - dh)/2 + (state.f1.y - .5) * bh * .8;\n\n    // rotação em torno do centro do carro (controle \"Rotação do veículo\")\n    if(state.edRot){\n      const rcx = dx + dw/2, rcy = dy + dh/2;\n      ctx.save();\n      ctx.translate(rcx, rcy);\n      ctx.rotate(state.edRot * Math.PI / 180);\n      ctx.translate(-rcx, -rcy);\n    }\n\n    // sombra elíptica suave no piso (só quando o carro está recortado)\n    if(state.foto1Cut){\n      const scx = dx + dw/2, scy = dy + dh - 8;\n      const sombra = ctx.createRadialGradient(scx, scy, 0, scx, scy, dw*.42);\n      sombra.addColorStop(0, 'rgba(0,0,0,.34)');\n      sombra.addColorStop(1, 'rgba(0,0,0,0)');\n      ctx.save();\n      ctx.translate(scx, scy);\n      ctx.scale(1, .16);\n      ctx.translate(-scx, -scy);\n      ctx.fillStyle = sombra;\n      ctx.beginPath(); ctx.arc(scx, scy, dw*.42, 0, Math.PI*2); ctx.fill();\n      ctx.restore();\n    }\n\n    ctx.drawImage(carro, dx, dy, dw, dh);\n    if(state.edRot) ctx.restore();\n  } else {\n    ctx.fillStyle = 'rgba(255,255,255,.4)';\n    ctx.font = '400 24px ' + ED.fonte;\n    ctx.textAlign = 'center';\n    ctx.fillText('ENVIE A FOTO PRINCIPAL E USE \"REMOVER FUNDO\"', W/2, 900);\n    ctx.textAlign = 'left';\n  }\n\n  // ---------- bottom: sombreamento espelhado ao do topo garante a\n  // legibilidade — textos claros sobre o véu escuro ----------\n  const RODAPE_Y = FEED ? 840 : 1400;\n  const rodape = ctx.createLinearGradient(0, RODAPE_Y, 0, H);\n  rodape.addColorStop(0, 'rgba(0,0,0,0)');\n  rodape.addColorStop(.45, 'rgba(0,0,0,.38)');\n  rodape.addColorStop(1, 'rgba(0,0,0,.66)');\n  ctx.fillStyle = rodape; ctx.fillRect(0, RODAPE_Y, W, H - RODAPE_Y);\n\n  const M = 76;\n  let y = FEED ? 978 : 1548;   // mesmos 372px até a base nos dois formatos\n\n  // rótulo de curadoria com filete vermelho\n  ctx.fillStyle = '#c33a39';\n  ctx.fillRect(M, y - 16, 42, 3);\n  edTextoEsq('SELEÇÃO ATTRA', M + 58, y - 8, '500 21px ' + ED.fonte, 7, '#d4d4da');\n\n  y += 66;\n  const marca = val('marca').toUpperCase();\n  if(marca) edTextoEsq(marca, M, y, '500 30px ' + ED.fonte, 9, '#e4e4e9');\n\n  y += 74;\n  const modelo = val('modelo').toUpperCase();\n  if(modelo){\n    let ms = 62;\n    ctx.font = `600 ${ms}px ` + ED.fonte;\n    while(ms > 36 && ctx.measureText(modelo).width > W - 2*M){\n      ms -= 2; ctx.font = `600 ${ms}px ` + ED.fonte;\n    }\n    ctx.fillStyle = '#ffffff';\n    ctx.fillText(modelo, M, y);\n  }\n\n  y += 56;\n  const meta = [\n    val('ano'),\n    val('km') ? val('km') + ' KM' : '',\n    val('kmextra').toUpperCase(),\n  ].filter(Boolean).join('   •   ');\n  if(meta) edTextoEsq(meta, M, y, '400 27px ' + ED.fonte, 3, '#cfcfd6');\n\n  y += 84;\n  const preco = val('preco').replace(/^R\\$\\s*/i, '');\n  if(preco){\n    const ptxt = 'R$ ' + preco;\n    let ps = 52;\n    ctx.font = `500 ${ps}px ` + ED.fonte;\n    while(ps > 34 && ctx.measureText(ptxt).width > W - 2*M){\n      ps -= 1; ctx.font = `500 ${ps}px ` + ED.fonte;\n    }\n    ctx.fillStyle = '#ffffff';\n    ctx.fillText(ptxt, M, y);\n  }\n}\n\n/* ================================================================\n   TIPO 5 — FICHA (claro: 3 detalhes + foto principal grande)\n\n   Sem recorte de fundo. As fotos do estoque são todas feitas no mesmo\n   lugar (fachada de vidro da loja, vegetação em cima, piso de concreto\n   claro embaixo, carro em 3/4), então em vez de \"flutuar\" o carro no\n   branco — o que exigiria recorte — as fotos entram EMOLDURADAS: cantos\n   arredondados e sombra suave. O fundo real vira parte da composição.\n================================================================ */\nfunction cantoArredondado(x, y, w, h, r){\n  ctx.beginPath();\n  ctx.moveTo(x + r, y);\n  ctx.arcTo(x + w, y,     x + w, y + h, r);\n  ctx.arcTo(x + w, y + h, x,     y + h, r);\n  ctx.arcTo(x,     y + h, x,     y,     r);\n  ctx.arcTo(x,     y,     x + w, y,     r);\n  ctx.closePath();\n}\n\n/**\n * Foto emoldurada em ASPECT FIT: a imagem entra INTEIRA, sem corte, e a moldura\n * se ajusta a ela em vez do contrário.\n *\n * A versão anterior preenchia a caixa (aspect fill) e descartava as bordas —\n * numa foto 1920x1440 dentro de uma caixa mais alta que larga isso jogava fora\n * quase metade da largura, cortando justamente a lateral do carro. Aqui a caixa\n * é o ESPAÇO MÁXIMO: a foto é reduzida até caber por inteiro e a sombra\n * acompanha o retângulo real da foto, então não sobra moldura vazia.\n *\n * `opt.zoom > 1` continua valendo para quem quiser fechar num detalhe — aí sim\n * o corte é intencional, e a moldura volta a ser a caixa cheia.\n */\nfunction fotoEmMoldura(img, x, y, w, h, opt, raio, preencher){\n  const r = raio === undefined ? 18 : raio;\n  const zoom = opt && opt.zoom ? opt.zoom : 1;\n  const px = opt && opt.x !== undefined ? opt.x : .5;\n  const py = opt && opt.y !== undefined ? opt.y : .5;\n\n  // O aspect fit mostra a foto INTEIRA — e por isso não há o que deslocar. Se\n  // ele valesse sempre, os controles de posição não fariam nada, que era\n  // exatamente o que acontecia. Então mexer na posição (ou no zoom) liga o modo\n  // recorte, onde o deslocamento passa a ser visível. `preencher` força o\n  // recorte para a foto ocupar a caixa toda — usado na foto principal, que\n  // precisa ficar alinhada com as de cima.\n  const moveu = Math.abs(px - .5) > 0.001 || Math.abs(py - .5) > 0.001;\n  let fx = x, fy = y, fw = w, fh = h, recortar = true;\n  if(img && zoom <= 1.001 && !moveu && !preencher){\n    // Aspect fit: encolhe até caber e centraliza no espaço disponível.\n    const escala = Math.min(w / img.width, h / img.height);\n    fw = img.width * escala;\n    fh = img.height * escala;\n    fx = x + (w - fw)/2;\n    fy = y + (h - fh)/2;\n    recortar = false;\n  }\n\n  ctx.save();\n  ctx.shadowColor = 'rgba(0,0,0,.18)';\n  ctx.shadowBlur = 26;\n  ctx.shadowOffsetY = 8;\n  ctx.fillStyle = '#e9e9ec';\n  cantoArredondado(fx, fy, fw, fh, r); ctx.fill();\n  ctx.restore();\n\n  ctx.save();\n  cantoArredondado(fx, fy, fw, fh, r); ctx.clip();\n  if(img){\n    if(recortar) drawPhoto(img, fx, fy, fw, fh, opt);\n    else ctx.drawImage(img, fx, fy, fw, fh);\n  } else {\n    ctx.fillStyle = '#dcdce1'; ctx.fillRect(fx, fy, fw, fh);\n    ctx.fillStyle = 'rgba(0,0,0,.32)';\n    ctx.font = '600 22px Montserrat, sans-serif';\n    ctx.textAlign = 'center';\n    ctx.fillText('FOTO', fx + fw/2, fy + fh/2 + 8);\n    ctx.textAlign = 'left';\n  }\n  ctx.restore();\n}\n\n/** Linha tracejada — assinatura do layout de referência. */\nfunction linhaTracejada(x1, y, x2, cor){\n  ctx.save();\n  ctx.strokeStyle = cor; ctx.lineWidth = 2;\n  ctx.setLineDash([7, 6]);\n  ctx.beginPath(); ctx.moveTo(x1, y); ctx.lineTo(x2, y); ctx.stroke();\n  ctx.restore();\n}\n\nfunction renderFicha(){\n  const FEED = H === H_FEED;   // 1080×1350: só a foto principal, rodapé fecha mais cedo\n  const M = 64;                    // margem lateral\n  ctx.fillStyle = '#ffffff'; ctx.fillRect(0, 0, W, H);\n\n  // Logo da casa no topo (a preta, porque o fundo é claro)\n  drawLogoBlack(W/2, 132, 300);\n\n  const marca  = val('marca').toUpperCase();\n  const modelo = val('modelo').toUpperCase();\n  const ano    = val('ano');\n  const km     = val('km');\n\n  if(marca) spacedText(marca, W/2, 250, '600 30px Montserrat, sans-serif', 14, RED);\n\n  let msize = 96;\n  while(msize > 44 && spacedWidth(modelo, `800 ${msize}px Montserrat, sans-serif`, 2) > W - 2*M){\n    msize -= 3;\n  }\n  if(modelo) spacedText(modelo, W/2, 340, `800 ${msize}px Montserrat, sans-serif`, 2, '#111114');\n\n  // Ano • km dentro de caixa tracejada\n  const anoKm = [ano, km ? km + 'km' : ''].filter(Boolean).join('  •  ');\n  if(anoKm){\n    ctx.font = '600 30px Montserrat, sans-serif';\n    const larg = ctx.measureText(anoKm).width + 56;\n    const cx = W/2 - larg/2, cy = 372, alt = 58;\n    ctx.save();\n    ctx.strokeStyle = RED; ctx.lineWidth = 2; ctx.setLineDash([7, 6]);\n    cantoArredondado(cx, cy, larg, alt, 8); ctx.stroke();\n    ctx.restore();\n    ctx.fillStyle = '#111114'; ctx.textAlign = 'center';\n    ctx.fillText(anoKm, W/2, cy + 39);\n    ctx.textAlign = 'left';\n  }\n\n  // Cores: rótulo fino + valor forte, com tracejado embaixo\n  // Rótulo é editável: a linha serve para qualquer informação, não só cor.\n  // Sem rótulo, mostra só o conteúdo (sem dois-pontos soltos).\n  const cores = [\n    { rotulo: val('rot1').toUpperCase(), valor: val('corext').toUpperCase() },\n    { rotulo: val('rot2').toUpperCase(), valor: val('corint').toUpperCase() },\n  ].filter(c => c.valor).map(c => ({ ...c, rotulo: c.rotulo ? c.rotulo + ':' : '' }));\n  let cy = 500;\n  for(const c of cores){\n    // Sem rótulo não entra o espaço separador, senão a linha fica deslocada.\n    const prefixo = c.rotulo ? c.rotulo + ' ' : '';\n    // A fonte encolhe até a linha caber: conteúdo pode ser longo\n    // (\"Preto Magno, fosca de fábrica\") e antes vazava pelas laterais.\n    let fs = 38;\n    const larguraDe = (tam) => {\n      ctx.font = `500 ${tam}px Montserrat, sans-serif`;\n      const r = ctx.measureText(prefixo).width;\n      ctx.font = `800 ${tam}px Montserrat, sans-serif`;\n      return r + ctx.measureText(c.valor).width;\n    };\n    while(fs > 22 && larguraDe(fs) > W - 2*M) fs -= 1;\n\n    ctx.font = `500 ${fs}px Montserrat, sans-serif`;\n    const wRot = ctx.measureText(prefixo).width;\n    ctx.font = `800 ${fs}px Montserrat, sans-serif`;\n    const wVal = ctx.measureText(c.valor).width;\n    const x0 = W/2 - (wRot + wVal)/2;\n    ctx.fillStyle = '#111114';\n    ctx.font = `500 ${fs}px Montserrat, sans-serif`;\n    ctx.fillText(prefixo, x0, cy);\n    ctx.font = `800 ${fs}px Montserrat, sans-serif`;\n    ctx.fillText(c.valor, x0 + wRot, cy);\n    linhaTracejada(x0 - 10, cy + 16, x0 + wRot + wVal + 10, RED);\n    cy += 66;\n  }\n\n  // ---- Tira de 3 detalhes (recortes verticais das fotos horizontais) ----\n  // Caixa quase quadrada de propósito: as fotos do estoque são horizontais\n  // (1920x1440) e uma caixa alta como a da referência descartaria quase metade\n  // da largura. Com 330 o corte cai de ~46% para ~30%, e o resto o operador\n  // escolhe pelo zoom/posição de cada foto.\n  // A caixa acompanha a proporção REAL da foto (4:3 do estoque): assim o aspect\n  // fit não deixa faixa vazia dentro da moldura. Largura da coluna x 3/4.\n  // DUAS fotos no topo, sempre. Com três, cada uma ficava com 233px de altura\n  // num canvas de 1920 — pequenas demais para ler um detalhe.\n  const tiraY = cy + 24, gap = 26;\n  const detalhes = [\n    { img: state.foto2, opt: state.f2 },\n    { img: state.foto3, opt: state.f3 },\n  ];\n  const larguraCol = (W - 2*M - gap) / 2;\n  const tiraH = Math.round(larguraCol * 3 / 4);\n  // Feed: sem a tira — a foto principal ocupa o lugar dela.\n  if(!FEED) detalhes.forEach((d, i) => {\n    fotoEmMoldura(d.img, M + i*(larguraCol + gap), tiraY, larguraCol, tiraH, d.opt, 14);\n  });\n\n  // ---- Foto principal, grande, com o fundo original ----\n  // Em 4:3 da largura útil, MAS limitada pelo que sobra até o rodapé: com a\n  // tira de 2 fotos (mais alta) o herói cheio empurraria o valor para fora do\n  // canvas. O menor dos dois mantém a peça inteira sempre dentro.\n  const heroY = FEED ? tiraY : tiraY + tiraH + gap;\n  // Reserva do rodapé: selo + valor + respiro na base.\n  const ALTURA_RODAPE = FEED ? 200 : 240;\n  const heroH = H - ALTURA_RODAPE - heroY;\n  // `preencher` = a foto principal ocupa a largura INTEIRA, alinhada com as\n  // bordas das duas de cima. Em aspect fit ela encolhia para caber na altura\n  // restante e ficava mais estreita que a tira, quebrando o alinhamento — o\n  // corte vertical de poucos por cento é preferível a esse desencontro.\n  fotoEmMoldura(state.foto1, M, heroY, W - 2*M, heroH, state.f1, 20, true);\n\n  // ---- Rodapé: selo + valor ----\n  let py = heroY + heroH + (FEED ? 72 : 92);\n  const selo = val('garantia').toUpperCase();\n  if(selo){\n    ctx.font = '800 40px Montserrat, sans-serif';\n    ctx.fillStyle = '#111114'; ctx.textAlign = 'center';\n    ctx.fillText(selo, W/2, py);\n    const ws = ctx.measureText(selo).width;\n    linhaTracejada(W/2 - ws/2 - 12, py + 18, W/2 + ws/2 + 12, RED);\n    ctx.textAlign = 'left';\n    py += 80;\n  }\n\n  const preco = val('preco').replace(/^R\\$\\s*/i, '');\n  if(preco){\n    ctx.textAlign = 'center';\n    ctx.font = '500 40px Montserrat, sans-serif';\n    const wRot = ctx.measureText('VALOR: ').width;\n    ctx.font = '800 46px Montserrat, sans-serif';\n    const wVal = ctx.measureText('R$ ' + preco).width;\n    const x0 = W/2 - (wRot + wVal)/2;\n    ctx.textAlign = 'left';\n    ctx.fillStyle = '#111114';\n    ctx.font = '500 40px Montserrat, sans-serif';\n    ctx.fillText('VALOR: ', x0, py);\n    ctx.font = '800 46px Montserrat, sans-serif';\n    ctx.fillText('R$ ' + preco, x0 + wRot, py);\n  }\n}\n\nfunction render(){\n  ctx.clearRect(0, 0, W, H);\n  ctx.imageSmoothingEnabled = true;\n  ctx.imageSmoothingQuality = 'high';\n  ctx.textAlign = 'left';\n  if(state.tipo === 'destaque') renderDestaque();\n  else if(state.tipo === 'estoque') renderEstoque();\n  else if(state.tipo === 'editorial') renderEditorial();\n  else if(state.tipo === 'ficha') renderFicha();\n  else if(state.tipo === 'classico-loja') renderClassicoLoja();\n  else renderClassicoOriginal();\n}\n\n/* ---------- Feed 4:5 (1080×1350) ----------\n * Mesma composição do Stories, só com a foto principal. Os `render*` leem a\n * altura em `H`; quando ela é H_FEED, cada um pula a foto de baixo e fecha o\n * rodapé mais cedo (procure `FEED` dentro deles). O topo de cada formato —\n * letreiro, título, enquadramento da foto principal — usa as MESMAS\n * coordenadas do Stories, de propósito: o que o operador calibrou nos sliders\n * vale igual nas duas peças.\n *\n * Sem prévia na tela (decisão de 24/08/2026): o Feed nasce num canvas fora da\n * tela só na hora de baixar, para o render ao vivo não ficar duas vezes mais\n * lento a cada movimento de slider.\n */\nconst cvFeed = document.createElement('canvas');\ncvFeed.width = W; cvFeed.height = H_FEED;\nfunction renderFeed(){\n  const ctxStories = ctx, hStories = H;\n  ctx = cvFeed.getContext('2d'); H = H_FEED;\n  try { render(); }\n  finally { ctx = ctxStories; H = hStories; }\n}\n\n/* ---------- monta os 4 carros do estoque ---------- */\nconst estDefaults = [\n  {nome:'Porsche 911 Carrera', ano:'2025/2026', km:'1.290', preco:'1.250.000', tag:'BLINDADO'},\n  {nome:'Mercedes AMG S 63 E Performance', ano:'2025/2025', km:'3.392', preco:'1.890.000', tag:'BLINDADO'},\n  {nome:'Audi RS Q8 TFSI', ano:'2020/2021', km:'12.584', preco:'790.000', tag:''},\n  {nome:'', ano:'', km:'', preco:'', tag:''},\n];\nconst estWrap = $('estoqueCars');\nestDefaults.forEach((d, i) => {\n  const div = document.createElement('div');\n  div.className = 'carblock';\n  div.innerHTML = `\n    <h4>CARRO ${i+1}</h4>\n    <label>Nome</label><input type=\"text\" id=\"e_nome${i}\" value=\"${d.nome}\">\n    <div class=\"row\">\n      <div><label>Ano</label><input type=\"text\" id=\"e_ano${i}\" value=\"${d.ano}\"></div>\n      <div><label>KM</label><input type=\"text\" id=\"e_km${i}\" value=\"${d.km}\"></div>\n    </div>\n    <div class=\"row\">\n      <div><label>Preço</label><input type=\"text\" id=\"e_preco${i}\" value=\"${d.preco}\"></div>\n      <div><label>Selo (opcional)</label><input type=\"text\" id=\"e_tag${i}\" value=\"${d.tag}\"></div>\n    </div>\n    <label>Foto</label><input type=\"file\" id=\"e_foto${i}\" accept=\"image/*\">`;\n  estWrap.appendChild(div);\n});\n\n/* ---------- eventos ---------- */\nfunction loadImg(file, cb){\n  const r = new FileReader();\n  r.onload = e => { const img = new Image(); img.onload = () => cb(img, e.target.result); img.src = e.target.result; };\n  r.readAsDataURL(file);\n}\nfunction reduzirParaEnvio(img){\n  // rembg não precisa de mais que ~1600px; reduzir evita 413 e acelera\n  const max = 2048;\n  const sc = Math.min(1, max / Math.max(img.width, img.height));\n  const c = document.createElement('canvas');\n  c.width = Math.round(img.width * sc); c.height = Math.round(img.height * sc);\n  c.getContext('2d').drawImage(img, 0, 0, c.width, c.height);\n  return c.toDataURL('image/jpeg', .88);\n}\n$('foto1').addEventListener('change', e => { if(e.target.files[0]) loadImg(e.target.files[0], (img) => { state.foto1 = img; state.foto1Data = reduzirParaEnvio(img); state.foto1Url = null; state.foto1Cut = null; $('rembg-status').textContent = 'Foto nova carregada — clique em REMOVER FUNDO para recortar.'; autoFrameFoto1(img); render(); }); });\n$('foto2').addEventListener('change', e => { if(e.target.files[0]) loadImg(e.target.files[0], img => { state.foto2 = img; render(); }); });\n$('foto3').addEventListener('change', e => { if(e.target.files[0]) loadImg(e.target.files[0], img => { state.foto3 = img; render(); }); });\n$('foto4').addEventListener('change', e => { if(e.target.files[0]) loadImg(e.target.files[0], img => { state.foto4 = img; render(); }); });\nfor(let i = 0; i < 4; i++){\n  $('e_foto'+i).addEventListener('change', (e => {\n    const idx = i;\n    return ev => { if(ev.target.files[0]) loadImg(ev.target.files[0], img => { state.estFotos[idx] = img; render(); }); };\n  })());\n  ['e_nome','e_ano','e_km','e_preco','e_tag'].forEach(p =>\n    $(p+i).addEventListener('input', render));\n}\n$('logofile').addEventListener('change', e => {\n  if(e.target.files[0]) loadImg(e.target.files[0], (img, data) => {\n    state.logo = img;\n    try{ localStorage.setItem('attra_logo', data); }catch(_){}\n    render();\n  });\n});\n$('clearlogo').addEventListener('click', () => {\n  state.logo = null; localStorage.removeItem('attra_logo'); $('logofile').value = ''; render();\n});\n\n// Campos da Ficha (rótulos, valores e selo) entram AQUI. Sem isso eles só\n// apareciam quando outra ação forçava um render — o que fazia a cor interna e\n// o selo parecerem \"chapados\", como se não fossem editáveis.\n['marca','modelo','ano','preco','km','kmextra','b1','b2','b3',\n 'selo','et1','et2','corte','pisoy','fatiapiso','sombra',\n 'rot1','corext','rot2','corint','garantia'].forEach(id =>\n  $(id).addEventListener('input', render));\n\n[['f1zoom','f1','zoom'],['f1x','f1','x'],['f1y','f1','y'],\n ['f2zoom','f2','zoom'],['f2x','f2','x'],['f2y','f2','y'],\n ['f3zoom','f3','zoom'],['f3x','f3','x'],['f3y','f3','y'],\n ['f4zoom','f4','zoom'],['f4x','f4','x'],['f4y','f4','y']]\n.forEach(([id, obj, key]) => {\n  // Mexer na POSIÇÃO não mexe no zoom.\n  //\n  // Havia aqui um \"zoom mínimo\" que subia para 112% assim que o operador\n  // arrastava posição. A premissa era que sem zoom não sobrava o que deslocar —\n  // e ela é falsa: drawPhoto calcula o curso como\n  // `Math.max(dw - rw, rw*.6)`, garantindo 60% da caixa de deslocamento mesmo\n  // quando a foto cabe exata. A posição sempre funcionou sozinha.\n  //\n  // O efeito colateral era grave no Clássico: arrastar a posição vertical\n  // ampliava a foto em 12% e comia a margem em volta do carro, sem o operador\n  // ter pedido zoom nenhum.\n  $(id).addEventListener('input', e => {\n    state[obj][key] = e.target.value/100;\n    render();\n  });\n});\n\n/* ---------- troca de tipo ---------- */\nfunction updateVisibility(){\n  const t = state.tipo;\n  // Os DOIS Clássicos compartilham o formulário: marca, destaques, corte e piso\n  // valem para ambos. O que os separa é o RECORTE — o Clássico original é\n  // anterior a ele e seu desenho nunca lê state.foto1Cut, então mostrar os\n  // controles ali seria oferecer um botão sem efeito.\n  const classico = t === 'classico' || t === 'classico-loja';\n  $('sec-edtema').style.display    = (t === 'editorial' || t === 'classico-loja') ? '' : 'none';\n  $('edrot-wrap').style.display    = t === 'editorial' ? '' : 'none';\n  $('piso-recorte-wrap').style.display = t === 'classico-loja' ? '' : 'none';\n  $('rembg-legend').textContent    = t === 'editorial'\n    ? 'Editorial — recorte da foto'\n    : 'Recorte — apaga só o piso da foto';\n  $('corte-wrap').style.display    = classico ? '' : 'none';\n  $('piso-wrap').style.display     = classico ? '' : 'none';\n  $('sec-busca').style.display     = t === 'estoque' ? 'none' : '';\n  $('sec-veiculo').style.display   = t === 'estoque' ? 'none' : '';\n  $('sec-destaques').style.display = classico ? '' : 'none';\n  $('sec-specs').style.display     = t === 'destaque' ? '' : 'none';\n  $('sec-ficha').style.display     = t === 'ficha' ? '' : 'none';\n  $('fichaslots').style.display    = t === 'ficha' ? '' : 'none';\n  $('sec-fotos').style.display     = t === 'estoque' ? 'none' : '';\n  $('sec-estoque').style.display   = t === 'estoque' ? '' : 'none';\n  $('kmextra-wrap').style.display  = classico ? '' : 'none';\n  $('fotos-extra').style.display   = (t === 'destaque' || t === 'ficha') ? '' : 'none';\n  // A Ficha usa DUAS fotos na tira. Deixar a terceira no formulário só produzia\n  // um campo que não aparece em lugar nenhum da peça.\n  $('foto4-wrap').style.display    = t === 'ficha' ? 'none' : '';\n  $('foto2-label').textContent     = t === 'destaque'\n    ? 'Foto de baixo 1 (interior / detalhe)' : 'Foto secundária (traseira / lateral — rodapé)';\n}\ndocument.querySelectorAll('.typebtn[data-tipo]').forEach(btn => {\n  btn.addEventListener('click', () => {\n    document.querySelectorAll('.typebtn[data-tipo]').forEach(b => b.classList.remove('active'));\n    btn.classList.add('active');\n    state.tipo = btn.dataset.tipo;\n    updateVisibility();\n    if(state.foto1) autoFrameFoto1(state.foto1);\n    render();\n  });\n});\n\n/* ---------- publicar no status do WhatsApp ---------- */\n$('publicarstatus').addEventListener('click', async () => {\n  const btn = $('publicarstatus');\n  const msg = $('statusmsg');\n  const legenda = val('statuscaption').trim();\n  const link = val('statuslink').trim();\n\n  if(!legenda){ msg.textContent = 'Escreva a legenda antes de publicar.'; return; }\n\n  // O link entra no FIM da legenda: no WhatsApp o preview do link é gerado\n  // pelo último link da mensagem, e um link no meio do texto some no meio dele.\n  const textoFinal = link ? (legenda + '\\n\\n' + link) : legenda;\n\n  // Publicar é público e não tem desfazer: vai para todos os contatos da\n  // instância e fica 24h no ar. A confirmação mostra o que será publicado.\n  const resumo = 'Publicar no Status do WhatsApp?\\n\\n' + textoFinal +\n    '\\n\\nIsso fica 24h no ar e todos os contatos da instância veem. Não tem desfazer.';\n  if(!confirm(resumo)) return;\n\n  btn.disabled = true;\n  const rotulo = btn.textContent;\n  btn.textContent = 'Publicando...';\n  msg.textContent = 'Enviando a imagem — pode levar alguns segundos.';\n\n  try{\n    const imagem = cv.toDataURL('image/jpeg', 0.88);\n    const r = await fetch('/api/admin/marketing/gerador-criativos/publicar-status', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ image: imagem, caption: textoFinal }),\n    });\n    const d = await r.json().catch(() => null);\n    if(!r.ok || !d || !d.ok){\n      msg.textContent = 'Não publicou: ' + ((d && (d.error || d.detalhe)) || ('HTTP ' + r.status));\n    } else {\n      const hora = d.timestamp ? new Date(d.timestamp).toLocaleTimeString('pt-BR') : '';\n      msg.textContent = 'Publicado' + (hora ? ' às ' + hora : '') + '. Fica 24h no ar.';\n    }\n  } catch(e){\n    msg.textContent = 'Falhou ao publicar: ' + (e && e.message ? e.message : e);\n  } finally {\n    btn.disabled = false;\n    btn.textContent = rotulo;\n  }\n});\n\n/* ---------- download: Stories + Feed, e os dois vão ao Marketing ---------- */\n// Cada clique baixa DUAS peças (NOME-STORIES-v1.png e NOME-FEED-v1.png) e envia\n// as duas ao board do Marketing (POST /creatives, um card por formato). Antes\n// havia um checkbox \"Enviar ao patrocinado\" que precisava ser marcado a cada\n// peça — quando esquecido, a peça era gerada e não chegava ao Marketing.\n// Agora não há opção: gerou, foi.\n$('download').addEventListener('click', () => {\n  const clean = s => s.replace(/\\s+/g, '-').replace(/[^\\w\\-\\.]/g, '').replace(/-+/g,'-');\n  let name;\n  if(state.tipo === 'estoque') name = 'Attra-Estoque';\n  else {\n    name = [val('marca'), val('modelo'), val('ano')].filter(Boolean).map(clean).join('-') || 'criativo-attra';\n    if(state.tipo === 'destaque') name += '-DESTAQUE';\n  }\n  const btn = $('download'), msg = $('downloadmsg');\n\n  // toBlob + Object URL: dataURL gigante falha silenciosamente no Safari\n  // (PNGs com textura passam fácil do limite) — blob não tem esse teto\n  const gerarPng = canvas => new Promise((res, rej) => {\n    try { canvas.toBlob(b => b ? res(b) : rej(new Error('Falha ao gerar o PNG — tente novamente.')), 'image/png'); }\n    catch(e){ rej(e); }\n  });\n  const baixar = (blob, arquivo) => {\n    const url = URL.createObjectURL(blob);\n    const a = document.createElement('a');\n    a.download = arquivo; a.href = url;\n    document.body.appendChild(a); a.click(); a.remove();\n    setTimeout(() => URL.revokeObjectURL(url), 4000);\n  };\n  const enviar = async (blob, formato) => {\n    const fd = new FormData();\n    fd.append('file', blob, name + '-' + formato.toUpperCase() + '.png');\n    fd.append('vehicle_name', name);\n    fd.append('format', formato);\n    const r = await fetch('/api/admin/marketing/creatives', { method: 'POST', body: fd });\n    if(r.ok) return;\n    const d = await r.json().catch(() => null);\n    throw new Error((d && d.error) || ('HTTP ' + r.status));\n  };\n\n  (async () => {\n    btn.disabled = true;\n    msg.textContent = 'Gerando Stories e Feed…';\n    try{\n      renderFeed();\n      const [stories, feed] = await Promise.all([gerarPng(cv), gerarPng(cvFeed)]);\n      baixar(stories, name + '-STORIES-v1.png');\n      baixar(feed, name + '-FEED-v1.png');\n      msg.textContent = 'Enviando os dois ao Marketing…';\n      const envios = await Promise.allSettled([enviar(stories, 'stories'), enviar(feed, 'feed')]);\n      const falhas = envios\n        .map((e, i) => e.status === 'rejected' ? (i ? 'Feed' : 'Stories') + ' (' + e.reason.message + ')' : null)\n        .filter(Boolean);\n      msg.textContent = falhas.length\n        ? 'Baixados, mas não chegaram ao Marketing: ' + falhas.join('; ')\n        : 'Stories 9:16 e Feed 4:5 baixados e enviados ao board do Marketing.';\n    } catch(err){\n      msg.textContent = 'Não foi possível exportar: ' + (err && err.message ? err.message : err);\n    } finally {\n      btn.disabled = false;\n    }\n  })();\n});\n\n/* ---------- init ---------- */\n/* ---------- busca no estoque (preenche os campos; manual continua valendo) ---------- */\nconst fmtBR = n => Number(n).toLocaleString('pt-BR');\n\nasync function buscarEstoque(){\n  const q = val('estoquebusca');\n  const box = $('estoqueresultados');\n  $('estoquefotos').innerHTML = '';\n  if(!q){ box.innerHTML = ''; return; }\n  box.innerHTML = '<div class=\"hint\">Buscando no estoque…</div>';\n  try{\n    const r = await fetch('/api/vehicles?search=' + encodeURIComponent(q) + '&limit=8');\n    const d = await r.json();\n    const vs = (d.vehicles || []).slice(0, 8);\n    if(!vs.length){ box.innerHTML = '<div class=\"hint\">Nenhum veículo encontrado para \"' + q + '\".</div>'; return; }\n    box.innerHTML = '';\n    for(const v of vs){\n      const b = document.createElement('button');\n      b.type = 'button'; b.className = 'estq-item';\n      b.textContent = [v.brand, v.model, v.version, v.year_model].filter(Boolean).join(' ')\n        + ' — R$ ' + fmtBR(v.price) + ' · ' + fmtBR(v.mileage) + ' km';\n      b.addEventListener('click', () => aplicarVeiculo(v));\n      box.appendChild(b);\n    }\n  }catch(_){\n    box.innerHTML = '<div class=\"hint\">Busca indisponível aqui — funciona dentro do admin do site (menu Criativos).</div>';\n  }\n}\n\nfunction aplicarVeiculo(v){\n  $('marca').value  = (v.brand || '').toUpperCase();\n  $('modelo').value = [v.model, v.version].filter(Boolean).join(' ').toUpperCase();\n  $('ano').value    = v.year_model || '';\n  $('preco').value  = v.price ? fmtBR(v.price) : '';\n  $('km').value     = v.mileage ? fmtBR(v.mileage) : '';\n  if(!val('b1') && v.color) $('b1').value = 'Cor ' + v.color;\n  sugerirLinkDoStatus(v);\n  montarFotosEstoque(v);\n  render();\n}\n\n/**\n * Preenche o link do status com a ficha do veículo, marcada com UTM.\n *\n * `utm_source=whatsapp` + `utm_medium=status` cai em \"social orgânico\" no\n * painel de visitantes — bucket real, não \"outros\". A campanha leva o slug do\n * carro, então dá para ver qual veículo o status trouxe. Sem isso a visita\n * chega como \"direto\" e não há como saber que veio daqui.\n */\nfunction sugerirLinkDoStatus(v){\n  if(!v || !v.slug) return;\n  const campo = $('statuslink');\n  if(!campo) return;\n  const p = new URLSearchParams({\n    utm_source: 'whatsapp',\n    utm_medium: 'status',\n    utm_campaign: v.slug,\n  });\n  campo.value = 'https://attraveiculos.com.br/veiculo/' + v.slug + '?' + p.toString();\n}\n\n/**\n * Posições das fotos que a Ficha usa, dentro da galeria do MESMO carro.\n * A 1 é sempre a principal (é a capa do anúncio); 2 e 11, no padrão de\n * fotografia da Attra, costumam cair em ângulos e detalhes bem diferentes —\n * evitam dois recortes quase iguais do mesmo lado do carro.\n *\n * São DUAS na tira de propósito: com três, cada foto 4:3 ficava com 233px de\n * altura e não dava para ler um detalhe.\n */\nconst FICHA_POSICOES = [1, 2, 11];\n\n/**\n * URL da foto do estoque na resolução NATIVA da origem.\n *\n * Medido em produção (18/08/2026): a foto na S3 é 1920x1440 e este proxy era\n * chamado com w=1080 — devolvia 1080x810, um terço dos pixels. Não aparecia em\n * zoom 1,0, onde a banda do Clássico usa exatamente 1080 de largura; passando\n * disso — que é o uso normal, fechar o enquadramento no carro — a foto era\n * ampliada a partir de uma fonte já reduzida, e a peça saía mole.\n *\n * w=1920 e q=90 porque AMBOS precisam constar em next.config.ts: q=95 devolve\n * HTTP 400, e pedir w acima de 1920 não adianta — o proxy não faz upscale.\n * Foto pequena continua pequena (540x420 medido), só com compressão melhor;\n * por isso a troca nunca piora nenhum caso.\n */\nconst urlFotoEstoque = u => '/_next/image?url=' + encodeURIComponent(u) + '&w=1920&q=90';\n\n/** Carrega a galeria do carro nas fotos da Ficha, respeitando quantas existem. */\nfunction preSelecionarFotosDaFicha(fotos){\n  if(!fotos || fotos.length === 0) return;\n  const alvos = ['foto1', 'foto2', 'foto3'];\n  // O terceiro detalhe começa vazio: a tira de 2 é o padrão. Limpa também um\n  // carro anterior, senão a foto dele sobrava na peça do carro novo.\n  state.foto4 = null;\n  // Menos fotos que o esperado: distribui ao longo da galeria em vez de repetir\n  // as primeiras, que costumam ser variações do mesmo ângulo.\n  const ultima = FICHA_POSICOES[FICHA_POSICOES.length - 1];\n  const posicoes = fotos.length >= ultima\n    ? FICHA_POSICOES\n    : [1, ...[1, 2].map(i => Math.min(fotos.length, 1 + Math.round(i * (fotos.length - 1) / 2)))];\n\n  posicoes.forEach((pos, i) => {\n    const url = fotos[Math.min(pos, fotos.length) - 1];\n    if(!url) return;\n    const img = new Image();\n    img.onload = () => {\n      state[alvos[i]] = img;\n      if(i === 0){\n        state.foto1Url = url; state.foto1Data = null; state.foto1Cut = null;\n        autoFrameFoto1(img);\n      }\n      render();\n    };\n    img.src = urlFotoEstoque(url);\n  });\n}\n\nfunction montarFotosEstoque(v){\n  const wrap = $('estoquefotos');\n  wrap.innerHTML = '';\n  if(state.tipo === 'ficha') preSelecionarFotosDaFicha(v.photos);\n  // /_next/image = proxy da própria origem → canvas continua exportável\n  for(const u of (v.photos || [])){\n    const t = document.createElement('img');\n    t.src = '/_next/image?url=' + encodeURIComponent(u) + '&w=256&q=60';\n    t.className = 'estq-thumb';\n    t.title = state.tipo === 'ficha'\n      ? 'Clique: aplica no destino selecionado acima'\n      : 'Clique: Foto principal · Shift+clique: Foto 2';\n    t.addEventListener('click', ev => {\n      // Na Ficha a tira usa foto2, foto3 e foto4, e o atalho antigo (clique /\n      // Shift+clique) só alcançava as duas primeiras — as outras duas ficavam\n      // sem caminho de seleção. Aqui o destino vem do seletor de slot.\n      const destino = state.tipo === 'ficha'\n        ? state.slotFoto\n        : (ev.shiftKey ? 'foto2' : 'foto1');\n      const img = new Image();\n      img.onload = () => {\n        state[destino] = img;\n        if(destino === 'foto1'){\n          // foto do estoque: o rembg recebe a URL pública (sem upload)\n          state.foto1Url = u;\n          state.foto1Data = null;\n          state.foto1Cut = null;\n          $('rembg-status').textContent = 'Foto do estoque selecionada — clique em REMOVER FUNDO para recortar.';\n          autoFrameFoto1(img);\n        }\n        marcarThumbUsada(t, destino);\n        if(state.tipo === 'ficha') avancarSlot();\n        render();\n      };\n      img.src = urlFotoEstoque(u);\n    });\n    wrap.appendChild(t);\n  }\n}\n\n/* ---------- destino da foto escolhida na galeria do estoque (Ficha) ---------- */\nconst SLOTS_FICHA = ['foto1', 'foto2', 'foto3'];\n\nfunction pintarSlotAtivo(){\n  document.querySelectorAll('.slotbtn').forEach(b => {\n    b.classList.toggle('active', b.dataset.slot === state.slotFoto);\n  });\n}\n\n/** Passa para o próximo destino, para dar pra clicar nas três em sequência. */\nfunction avancarSlot(){\n  const i = SLOTS_FICHA.indexOf(state.slotFoto);\n  state.slotFoto = SLOTS_FICHA[(i + 1) % SLOTS_FICHA.length];\n  pintarSlotAtivo();\n}\n\n/** Marca visualmente qual miniatura foi usada e em qual destino. */\nfunction marcarThumbUsada(thumb, destino){\n  const rotulos = { foto1: 'P', foto2: '1', foto3: '2', foto4: '3' };\n  document.querySelectorAll('.estq-thumb').forEach(el => {\n    if(el.dataset.destino === destino){ el.classList.remove('usada'); delete el.dataset.destino; }\n  });\n  thumb.classList.add('usada');\n  thumb.dataset.destino = destino;\n  thumb.title = 'Aplicada em: ' + (rotulos[destino] === 'P' ? 'Principal' : 'Detalhe ' + rotulos[destino]);\n}\n\ndocument.querySelectorAll('.slotbtn').forEach(btn => {\n  btn.addEventListener('click', () => {\n    state.slotFoto = btn.dataset.slot;\n    pintarSlotAtivo();\n  });\n});\n\n/* ---------- recorte de fundo via IA (Replicate, rota do admin) ---------- */\ndocument.querySelectorAll('.pisobtn').forEach(btn => {\n  btn.addEventListener('click', () => {\n    document.querySelectorAll('.pisobtn').forEach(b => b.classList.remove('active'));\n    btn.classList.add('active');\n    state.pisoTipo = btn.dataset.piso;\n    render();\n  });\n});\n\n$('edrot').addEventListener('input', e => {\n  state.edRot = parseInt(e.target.value, 10) || 0;\n  render();\n});\n\n// Desfazer o recorte. Antes a única saída era reenviar a foto — o próprio\n// status dizia \"troque a foto para recortar outra\". Comparar com e sem recorte\n// é a operação mais frequente aqui; exigir reenvio de arquivo era atrito à toa.\n$('rembgundo').addEventListener('click', () => {\n  state.foto1Cut = null;\n  $('rembgundo').style.display = 'none';\n  $('rembg-status').textContent = 'Voltou para a foto original, com o fundo dela.';\n  render();\n});\n\n$('rembgbtn').addEventListener('click', async () => {\n  const st = $('rembg-status');\n  if(!state.foto1Data && !state.foto1Url){ st.textContent = 'Envie a Foto principal (ou selecione uma do estoque) primeiro.'; return; }\n  if(state.foto1Cut){ st.textContent = 'Esta foto já está recortada — troque a foto para recortar outra.'; return; }\n  $('rembgbtn').disabled = true;\n  st.textContent = 'Recortando o fundo via IA… (10-30s, não feche a aba)';\n  try{\n    const r = await fetch('/api/admin/marketing/gerador-criativos/rembg', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify(state.foto1Url ? { imageUrl: state.foto1Url } : { image: state.foto1Data }),\n    });\n    const d = await r.json().catch(() => ({}));\n    if(!r.ok) throw new Error(d.error || ('HTTP ' + r.status));\n    if(!d.accepted){\n      state.foto1Cut = null;\n      const nota = typeof d.score === 'number' ? d.score + '%' : '?';\n      st.textContent = 'Recorte incerto (' + nota + ') — usando a foto ORIGINAL pra preservar a qualidade. O carro aparece inteiro.';\n      render();\n      return;\n    }\n    const img = new Image();\n    img.onload = () => {\n      state.foto1Cut = img;\n      // O enquadramento padrão do Clássico (zoom .88, y .18) foi calibrado\n      // para foto inteira; aplicado ao recorte, afundava o carro ~80px e\n      // empurrava todo o bloco de texto para cima da foto 2. Recorte entra\n      // com enquadramento neutro; os sliders continuam valendo.\n      state.f1 = {zoom: 1, x: .5, y: .5};\n      $('f1zoom').value = 100; $('f1x').value = 50; $('f1y').value = 50;\n      $('rembgundo').style.display = '';\n      const conf = typeof d.score === 'number' ? ' (confiança ' + d.score + '%)' : '';\n      st.textContent = 'Fundo removido ✓' + conf + ' — ajuste zoom/posição nos sliders da Foto 1.';\n      render();\n    };\n    img.src = d.image;\n  }catch(err){\n    st.textContent = 'Falha no recorte: ' + err.message + ' — dentro do admin do site, tente de novo.';\n  }finally{\n    $('rembgbtn').disabled = false;\n  }\n});\n\n$('estoquebtn').addEventListener('click', buscarEstoque);\n$('estoquebusca').addEventListener('keydown', e => {\n  if(e.key === 'Enter'){ e.preventDefault(); buscarEstoque(); }\n});\n\nconst savedLogo = (()=>{ try{ return localStorage.getItem('attra_logo'); }catch(_){ return null; } })();\nif(savedLogo){ const img = new Image(); img.onload = () => { state.logo = img; render(); }; img.src = savedLogo; }\n\nupdateVisibility();\nrender();\nif(document.fonts && document.fonts.ready) document.fonts.ready.then(render);\nsetTimeout(render, 800);\n</script>\n</body>\n</html>\n"
